INSERT INTO public.passages (id, class, subject, kind, title, content, word_count, theme)
VALUES (
  'c9-hindi-p01',
  9,
  'hindi',
  'gadya',
  'समय का सदुपयोग और मानव जीवन',
  'मानव जीवन में समय का सर्वाधिक महत्त्व है। बीता हुआ धन, स्वास्थ्य और वैभव पुनः प्राप्त किए जा सकते हैं, परंतु हाथ से निकला हुआ एक भी क्षण कभी वापस नहीं आता। समय की गति अविरल और निरंतर है, जो किसी भी सम्राट या बलवान के आदेश की प्रतीक्षा नहीं करती। जो व्यक्ति समय के प्रत्येक पल का मूल्य समझकर उसका सदुपयोग करते हैं, सफलता स्वयं उनके चरण चूमती है। इतिहास साक्षी है कि संसार के सभी महान व्यक्तियों ने समय की पाबंदी और अनुशासन को अपने जीवन का मूलमंत्र बनाया था। इसके विपरीत, जो लोग आज का कार्य कल पर टालते हैं और आलस्य में जीवन व्यतीत करते हैं, वे अंततः पश्चाताप के अतिरिक्त कुछ भी प्राप्त नहीं कर पाते। समय रूपी अमूल्य संपदा का उचित प्रबंधन ही व्यक्ति को उन्नति के सर्वोच्च शिखर पर पहुँचाता है। अतः प्रत्येक विद्यार्थी का यह प्रथम कर्तव्य है कि वह अपनी दिनचर्या निर्धारित करे और समय का सार्थक उपयोग करे।',
  158,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  word_count = EXCLUDED.word_count;

INSERT INTO public.passages (id, class, subject, kind, title, content, word_count, theme)
VALUES (
  'c9-hindi-p02',
  9,
  'hindi',
  'gadya',
  'पर्यावरण संरक्षण और भावी पीढ़ी',
  'प्रकृति और मानव का संबंध आदिकाल से अत्यंत घनिष्ठ रहा है। शुद्ध वायु, शीतल जल, हरी-भरी वनस्पतियाँ और उपजाऊ भूमि हमें प्रकृति से उपहार स्वरूप मिले हैं। परंतु वर्तमान भौतिकवादी युग में मानव ने अपने तात्कालिक स्वार्थ के वशीभूत होकर प्राकृतिक संसाधनों का अंधाधुंध दोहन किया है। वनों की अनियंत्रित कटाई और कल-कारखानों से निकलने वाले धुएँ ने वायुमंडल को अत्यंत विषैला बना दिया है। परिणामस्वरूप ऋतु-चक्र में असंतुलन, भूमंडलीय तापमान में वृद्धि और जल-संकट जैसी गंभीर समस्याएँ संपूर्ण मानवता के समक्ष उत्पन्न हो गई हैं। यदि हम अब भी सचेत नहीं हुए, तो आने वाली पीढ़ियों के लिए यह धरा रहने योग्य नहीं बचेगी। पर्यावरण की रक्षा करना केवल शासन का दायित्व नहीं है, अपितु प्रत्येक नागरिक का पुनीत धर्म है। हमें अधिक से अधिक वृक्षारोपण करना होगा, जल का अपव्यय रोकना होगा और प्लास्टिक के उपयोग का त्याग करना होगा।',
  142,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  word_count = EXCLUDED.word_count;

INSERT INTO public.passages (id, class, subject, kind, title, content, word_count, theme)
VALUES (
  'c9-hindi-p03',
  9,
  'hindi',
  'gadya',
  'स्वाध्याय और पुस्तकों का महत्त्व',
  'पुस्तकों को मानव का सच्चा और निष्कपट मित्र माना गया है। पुस्तकें ज्ञान का ऐसा असीम भंडार हैं जो देश और काल की सीमाओं से परे मनुष्य का उचित मार्गदर्शन करती हैं। स्वाध्याय की प्रवृत्ति व्यक्ति के चिंतन को उदार बनाती है तथा उसके भीतर विवेक, सदाचार और मानवीय संवेदनाओं का विकास करती है। जब संसार की अन्य वस्तुएँ या संगति हमें निराश कर देती हैं, तब श्रेष्ठ ग्रंथ एकांत में भी हमें आशा और संबल प्रदान करते हैं। एक अच्छी पुस्तक पढ़ने से हमारी कल्पनाशक्ति का विस्तार होता है और भाषा-शैली समृद्ध बनती है। दैनिक जीवन में स्वाध्याय को स्थान देने वाला मनुष्य कभी कुंठित या संकीर्ण नहीं होता। आज के डिजिटल युग में भी मुद्रित पुस्तकों का महत्त्व तनिक भी कम नहीं हुआ है। पुस्तकें हमारी आत्मा को आलोकित करती हैं। अतः जीवन को सार्थक बनाने के लिए प्रतिदिन उत्तम पुस्तकों का अध्ययन अवश्य करना चाहिए।',
  148,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  word_count = EXCLUDED.word_count;

INSERT INTO public.passages (id, class, subject, kind, title, content, word_count, theme)
VALUES (
  'c9-hindi-p04',
  9,
  'hindi',
  'gadya',
  'वैज्ञानिक दृष्टिकोण और अंधविश्वास',
  'आधुनिक युग विज्ञान और तकनीकी प्रगति का स्वर्णिम युग है। वैज्ञानिक दृष्टिकोण का वास्तविक अर्थ केवल प्रयोगशालाओं में नए आविष्कार करना नहीं है, बल्कि अपने दैनिक जीवन और विचारों में तर्क, विवेक तथा वस्तुनिष्ठता को अपनाना है। किसी भी विचार या मान्यता को बिना जांचे-परखे केवल रूढ़िवादिता के कारण स्वीकार कर लेना अंधविश्वास को जन्म देता है। अंधविश्वास समाज की बौद्धिक प्रगति में सबसे बड़ा अवरोधक सिद्ध होता है। जब कोई समाज वैज्ञानिक चेतना से संपन्न होता है, तब वह सामाजिक कुरीतियों, संकीर्णताओं और भ्रांतियों से मुक्त होकर सत्य की दिशा में आगे बढ़ता है। वैज्ञानिक दृष्टिकोण हमें प्रश्न पूछने, जिज्ञासा प्रकट करने और तथ्यों की कसौटी पर निष्कर्ष निकालने का साहस देता है। विद्यालयीन शिक्षा का परम लक्ष्य विद्यार्थियों में इसी स्वतंत्र और तर्कसंगत विचार-प्रणाली को विकसित करना है, जिससे एक प्रबुद्ध और प्रगतिशील राष्ट्र का निर्माण संभव हो सके।',
  141,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  word_count = EXCLUDED.word_count;

INSERT INTO public.passages (id, class, subject, kind, title, content, word_count, theme)
VALUES (
  'c9-hindi-p05',
  9,
  'hindi',
  'padya',
  'कर्मवीर की साधना',
  'देख बाधा विविध, बहु विघ्न घबराते नहीं,
रह भरोसे भाग्य के, दुःख भोग पछताते नहीं।
काम कितना ही कठिन हो, किंतु उकताते नहीं,
भीड़ में चंचल बने, जो वीर दिखलाते नहीं।
हो गए एक आन में, उनके बुरे दिन भी भले,
सब जगह सब काल में, वे ही मिले फूले-फले।
व्योम को छूते हुए, दुर्गम पहाड़ों पर चढ़े,
धैर्य का संबल लिए, जो नित्य आगे ही बढ़े।',
  67,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  word_count = EXCLUDED.word_count;

INSERT INTO public.passages (id, class, subject, kind, title, content, word_count, theme)
VALUES (
  'c9-hindi-p06',
  9,
  'hindi',
  'padya',
  'प्रकृति का अनुपम संदेश',
  'पर्वत कहता शीश उठाकर, तुम भी ऊँचे बन जाओ,
सागर कहता है लहराकर, मन में गहराई लाओ।
समझ रहे हो क्या कहती है, उठ-उठ गिर-गिर तरल तरंग,
भर लो भर लो अपने मन में, मीठी-मीठी मृदुल उमंग।
पृथ्वी कहती धैर्य न छोड़ो, कितना ही हो सिर पर भार,
नभ कहता है फैलो इतना, ढक लो तुम सारा संसार।
सूरज कहता नित्य प्रकाशित, नव प्रभात तुम बन जाओ,
चंदा कहता शीतल बनकर, सबके कष्ट मिटाओ।',
  74,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  word_count = EXCLUDED.word_count;

