  'c9-hindi-049',
  9,
  'hindi',
  'संधि',
  'image',
  'medium',
  'प्रस्तुत स्वर संधि संचित्र का अध्ययन कीजिए। ''अ/आ + इ/ई = ए'' तथा ''अ/आ + उ/ऊ = ओ'' का नियम किस संधि के बॉक्स में दर्शाया गया है?',
  '["गुण संधि","दीर्घ संधि","वृद्धि संधि","यण संधि"]'::jsonb,
  '{"kind":"svg","src":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540 200\" width=\"100%\" height=\"200\" style=\"background:#f0fdf4;border-radius:8px;font-family:''Noto Sans Devanagari'',sans-serif;\"><rect x=\"195\" y=\"10\" width=\"150\" height=\"35\" rx=\"8\" fill=\"#16a34a\" /><text x=\"270\" y=\"33\" fill=\"#ffffff\" font-size=\"15\" font-weight=\"bold\" text-anchor=\"middle\">स्वर संधि के भेद</text><g transform=\"translate(10, 65)\"><rect x=\"0\" y=\"0\" width=\"95\" height=\"110\" rx=\"6\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"1.5\" /><text x=\"47\" y=\"25\" fill=\"#14532d\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\">दीर्घ संधि</text><text x=\"47\" y=\"55\" fill=\"#166534\" font-size=\"11\" text-anchor=\"middle\">अ+अ=आ</text><text x=\"47\" y=\"80\" fill=\"#166534\" font-size=\"11\" text-anchor=\"middle\">इ+इ=ई</text></g><g transform=\"translate(115, 65)\"><rect x=\"0\" y=\"0\" width=\"95\" height=\"110\" rx=\"6\" fill=\"#fef9c3\" stroke=\"#ca8a04\" stroke-width=\"2\" /><text x=\"47\" y=\"25\" fill=\"#854d0e\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\">गुण संधि</text><text x=\"47\" y=\"55\" fill=\"#713f12\" font-size=\"11\" text-anchor=\"middle\">अ+इ=ए</text><text x=\"47\" y=\"80\" fill=\"#713f12\" font-size=\"11\" text-anchor=\"middle\">अ+उ=ओ</text></g><g transform=\"translate(220, 65)\"><rect x=\"0\" y=\"0\" width=\"95\" height=\"110\" rx=\"6\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"1.5\" /><text x=\"47\" y=\"25\" fill=\"#14532d\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\">वृद्धि संधि</text><text x=\"47\" y=\"55\" fill=\"#166534\" font-size=\"11\" text-anchor=\"middle\">अ+ए=ऐ</text><text x=\"47\" y=\"80\" fill=\"#166534\" font-size=\"11\" text-anchor=\"middle\">अ+ओ=औ</text></g><g transform=\"translate(325, 65)\"><rect x=\"0\" y=\"0\" width=\"95\" height=\"110\" rx=\"6\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"1.5\" /><text x=\"47\" y=\"25\" fill=\"#14532d\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\">यण संधि</text><text x=\"47\" y=\"55\" fill=\"#166534\" font-size=\"11\" text-anchor=\"middle\">इ+स्वर=य्</text><text x=\"47\" y=\"80\" fill=\"#166534\" font-size=\"11\" text-anchor=\"middle\">उ+स्वर=व्</text></g><g transform=\"translate(430, 65)\"><rect x=\"0\" y=\"0\" width=\"95\" height=\"110\" rx=\"6\" fill=\"#dcfce7\" stroke=\"#15803d\" stroke-width=\"1.5\" /><text x=\"47\" y=\"25\" fill=\"#14532d\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\">अयादि संधि</text><text x=\"47\" y=\"55\" fill=\"#166534\" font-size=\"11\" text-anchor=\"middle\">ए+स्वर=अय</text><text x=\"47\" y=\"80\" fill=\"#166534\" font-size=\"11\" text-anchor=\"middle\">ओ+स्वर=अव</text></g></svg>","alt":"स्वर संधि के 5 भेद संचित्र"}'::jsonb,
