INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c9-maths-026',
  9,
  'maths',
  'Circles',
  'image',
  'medium',
  'In the given diagram, O is the centre of the circle and arc AB subtends an angle ∠AOB = 110° at the centre. Find the angle ∠APB subtended by arc AB at point P on the alternate segment.',
  '["55°","70°","110°","220°"]'::jsonb,
  '{"kind":"svg","src":"<svg viewBox=\"0 0 300 240\" width=\"100%\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"150\" cy=\"120\" r=\"80\" fill=\"#f8fafc\" stroke=\"#1b2a4a\" stroke-width=\"2\"/><circle cx=\"150\" cy=\"120\" r=\"4\" fill=\"#dc2626\"/><text x=\"155\" y=\"115\" font-size=\"14\" font-weight=\"bold\" fill=\"#1b2a4a\">O</text><circle cx=\"90\" cy=\"170\" r=\"4\" fill=\"#0284c7\"/><text x=\"75\" y=\"185\" font-size=\"14\" font-weight=\"bold\" fill=\"#0284c7\">A</text><circle cx=\"210\" cy=\"170\" r=\"4\" fill=\"#0284c7\"/><text x=\"215\" y=\"185\" font-size=\"14\" font-weight=\"bold\" fill=\"#0284c7\">B</text><circle cx=\"150\" cy=\"40\" r=\"4\" fill=\"#16a34a\"/><text x=\"145\" y=\"32\" font-size=\"14\" font-weight=\"bold\" fill=\"#16a34a\">P</text><line x1=\"150\" y1=\"120\" x2=\"90\" y2=\"170\" stroke=\"#dc2626\" stroke-width=\"2\"/><line x1=\"150\" y1=\"120\" x2=\"210\" y2=\"170\" stroke=\"#dc2626\" stroke-width=\"2\"/><line x1=\"90\" y1=\"170\" x2=\"150\" y2=\"40\" stroke=\"#0284c7\" stroke-width=\"2\"/><line x1=\"210\" y1=\"170\" x2=\"150\" y2=\"40\" stroke=\"#0284c7\" stroke-width=\"2\"/><text x=\"130\" y=\"150\" font-size=\"13\" font-weight=\"bold\" fill=\"#dc2626\">110°</text><text x=\"142\" y=\"65\" font-size=\"13\" font-weight=\"bold\" fill=\"#16a34a\">?</text></svg>"}'::jsonb,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c9-maths-026',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'By NCERT Theorem 10.8, the angle subtended by an arc at the centre is double the angle subtended by it at any point on the remaining part of the circle. Hence ∠APB = (1/2) × ∠AOB = (1/2) × 110° = 55°.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c9-maths-027',
  9,
  'maths',
  'Lines and Angles',
  'image',
  'easy',
  'In the diagram, lines AB and CD are parallel (AB || CD) and EF is a transversal. If angle ∠1 = 65°, find the measure of the alternate interior angle ∠2.',
  '["65°","115°","125°","180°"]'::jsonb,
  '{"kind":"svg","src":"<svg viewBox=\"0 0 320 200\" width=\"100%\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"20\" y1=\"60\" x2=\"300\" y2=\"60\" stroke=\"#1b2a4a\" stroke-width=\"2.5\"/><text x=\"290\" y=\"50\" font-size=\"13\" font-weight=\"bold\" fill=\"#1b2a4a\">AB</text><line x1=\"20\" y1=\"140\" x2=\"300\" y2=\"140\" stroke=\"#1b2a4a\" stroke-width=\"2.5\"/><text x=\"290\" y=\"130\" font-size=\"13\" font-weight=\"bold\" fill=\"#1b2a4a\">CD</text><line x1=\"80\" y1=\"20\" x2=\"240\" y2=\"180\" stroke=\"#dc2626\" stroke-width=\"2.5\"/><text x=\"70\" y=\"25\" font-size=\"13\" font-weight=\"bold\" fill=\"#dc2626\">E</text><text x=\"245\" y=\"185\" font-size=\"13\" font-weight=\"bold\" fill=\"#dc2626\">F</text><text x=\"135\" y=\"85\" font-size=\"14\" font-weight=\"bold\" fill=\"#0284c7\">∠1 = 65°</text><text x=\"165\" y=\"132\" font-size=\"14\" font-weight=\"bold\" fill=\"#16a34a\">∠2 = ?</text></svg>"}'::jsonb,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c9-maths-027',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'When two parallel lines are cut by a transversal, pair of alternate interior angles are equal. Therefore, ∠2 = ∠1 = 65°.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

