INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-biology-098',
  '"ordered"'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  '["External nostrils filter incoming air through fine nasal hairs and mucus membranes.","Inhaled air traverses the pharynx and larynx past the epiglottis into the trachea.","Air branches into primary bronchi and progressively narrower bronchiole networks.","Air fills microscopic balloon-like alveoli surrounded by dense capillary meshworks.","Oxygen diffuses across the ultra-thin alveolar-capillary barrier and binds to hemoglobin in red blood cells."]'::jsonb,
  'Airway pathway: Nostrils -> Pharynx/Larynx/Trachea -> Bronchi and Bronchioles -> Alveoli -> Capillary diffusion.'
) ON CONFLICT (question_id) DO UPDATE SET
