) VALUES (
  'c10-biology-099',
  '"ordered"'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  '["Fertilization of ovum by sperm in the fallopian tube produces a single diploid zygote.","Zygote undergoes repeated cleavage divisions while traveling toward the uterus, forming a blastocyst.","The blastocyst embeds securely into the thickened endometrium of the uterine wall (implantation).","Embryo develops organs and receives nourishment through the placenta during the 9-month gestation period.","Coordinated uterine muscular contractions induce labour, culminating in parturition (childbirth)."]'::jsonb,
  'Developmental sequence: Fertilization -> Cleavage to blastocyst -> Implantation -> Gestation with placenta -> Parturition.'
) ON CONFLICT (question_id) DO UPDATE SET
