INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-chemistry-015',
  '5.6'::jsonb,
  NULL,
  NULL,
  0.1,
  NULL,
  NULL,
  'Molar mass of CaCO₃ = 40 + 12 + 48 = 100 g/mol. Moles of CaCO₃ = 10.0 / 100 = 0.10 mol. Stoichiometric ratio is 1:1, producing 0.10 mol CaO. Molar mass of CaO = 40 + 16 = 56 g/mol. Mass of CaO = 0.10 mol × 56 g/mol = 5.6 g.'
) ON CONFLICT (question_id) DO UPDATE SET
