INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-chemistry-088',
  '36'::jsonb,
  NULL,
  NULL,
  0.2,
  NULL,
  NULL,
  'Molar mass of H₂ = 2 g/mol. Moles of H₂ = 4.0 / 2 = 2.0 mol. Stoichiometric ratio: 2 mol H₂ yields 2 mol H₂O. Molar mass of H₂O = 2(1) + 16 = 18 g/mol. Mass of H₂O produced = 2.0 mol × 18 g/mol = 36.0 g.'
) ON CONFLICT (question_id) DO UPDATE SET
