  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c10-english-039',
  10,
  'english',
  'Grammar',
  'match',
  'medium',
  'Match each erroneous sentence with its corrected version and grammatical rationale:',
  NULL,
  NULL,
  NULL,
  NULL,
  2,
  '["Error: ''He ran fastly to reach the station''","Error: ''One of the student was absent''","Error: ''She is senior than me in service''","Error: ''Despite of his illness, he passed''"]'::jsonb,
  '["Correction: ''Despite his illness, he passed'' (''despite'' never takes the preposition ''of'')","Correction: ''She is senior to me in service'' (Latin comparatives like senior take preposition ''to'')","Correction: ''One of the students was absent'' (''one of the'' must be followed by a plural noun)","Correction: ''He ran fast to reach the station'' (''fast'' functions as both adjective and adverb)"]'::jsonb,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
