  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-english-039',
  NULL,
  NULL,
  NULL,
  NULL,
  '[["Error: ''He ran fastly to reach the station''","Correction: ''He ran fast to reach the station'' (''fast'' functions as both adjective and adverb)"],["Error: ''One of the student was absent''","Correction: ''One of the students was absent'' (''one of the'' must be followed by a plural noun)"],["Error: ''She is senior than me in service''","Correction: ''She is senior to me in service'' (Latin comparatives like senior take preposition ''to'')"],["Error: ''Despite of his illness, he passed''","Correction: ''Despite his illness, he passed'' (''despite'' never takes the preposition ''of'')"]]'::jsonb,
  NULL,
  'Common editing rules: ''Fast'' has no -ly form; ''one of the'' requires plural noun; ''senior/junior/prior'' take ''to''; ''despite'' takes no ''of''.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
