) VALUES (
  'c10-hindi-075',
  10,
  'hindi',
  'ततांरा-वामीरो कथा',
  'ordering',
  'medium',
  '''ततांरा-वामीरो कथा'' के प्रमुख घटनाक्रम को कहानी के सही कालक्रमानुसार व्यवस्थित कीजिए:',
  NULL,
  NULL,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  '["द्वीप का दो टुकड़ों (कार-निकोबार और लपाती) में विभक्त होना और सदियों पुरानी रूढ़ि का सदैव के लिए समाप्त होना।","पशु-पर्व के उत्सव में वामीरो की माँ द्वारा ततांरा को भरी सभा में अपमानित करना।","ततांरा द्वारा अत्यधिक क्रोध और निराशा में अपनी काठ की तलवार को धरती में घोंपकर पूरे बल से खींचना।","दिनभर के परिश्रम के बाद ततांरा का शाम को समुद्र तट पर शांत बैठना।","वामीरो द्वारा मधुर स्वर में प्रेम-गीत गाना और ततांरा का सम्मोहित होकर गीत पूरा करने का आग्रह करना।"]'::jsonb,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
