  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-hindi-075',
  '"ordered"'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  '["दिनभर के परिश्रम के बाद ततांरा का शाम को समुद्र तट पर शांत बैठना।","वामीरो द्वारा मधुर स्वर में प्रेम-गीत गाना और ततांरा का सम्मोहित होकर गीत पूरा करने का आग्रह करना।","पशु-पर्व के उत्सव में वामीरो की माँ द्वारा ततांरा को भरी सभा में अपमानित करना।","ततांरा द्वारा अत्यधिक क्रोध और निराशा में अपनी काठ की तलवार को धरती में घोंपकर पूरे बल से खींचना।","द्वीप का दो टुकड़ों (कार-निकोबार और लपाती) में विभक्त होना और सदियों पुरानी रूढ़ि का सदैव के लिए समाप्त होना।"]'::jsonb,
  'कथा का क्रमिक विकास: समुद्र तट पर बैठना -> वामीरो का गीत व सम्मोहन -> पशु-पर्व में अपमान -> तलवार से धरती चीरना -> द्वीप का विभक्त होना व परंपरा का टूटना।'
) ON CONFLICT (question_id) DO UPDATE SET
