  NULL,
  '["कर्नल और लेफ्टिनेंट का रात के समय खेमे में बैठकर वज़ीर अली की देशभक्ति और सादत अली के षड्यंत्र पर चर्चा करना।","दूर से घनी धूल उड़ती देखकर पहरेदार का कर्नल को एक तेज घुड़सवार के आने की सूचना देना।","सवार का तंबू में प्रवेश करके कर्नल से एकांत में बातचीत करने की माँग करना।","सवार द्वारा वज़ीर अली को गिरफ्तार करने के बहाने कर्नल से दस कारतूस माँगना और कर्नल का उसे कारतूस सौंप देना।","सवार द्वारा अपना वास्तविक नाम ''वज़ीर अली'' बताना और कर्नल का स्तब्ध व हक्का-बक्का रह जाना।"]'::jsonb,
  'घटनाक्रम का सही क्रम: कर्नल-लेफ्टिनेंट की चर्चा -> धूल उड़ती देखना व सवार का आगमन -> एकांत की माँग -> कारतूस माँगना -> वज़ीर अली द्वारा पहचान बताना व कर्नल का स्तब्ध रह जाना।'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c10-maths-001',
  10,
  'maths',
  'Real Numbers',
  'mcq',
  'easy',
  'According to the Fundamental Theorem of Arithmetic, every composite natural number can be uniquely factorized into a product of prime powers. What is the prime factorization of 156?',
  '["2² × 3 × 13","2 × 3² × 13","2³ × 3 × 7","2² × 3² × 11"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-maths-001',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Successive prime division: 156 ÷ 2 = 78; 78 ÷ 2 = 39; 39 ÷ 3 = 13; 13 ÷ 13 = 1. Therefore, 156 = 2² × 3 × 13.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
