  'mcq',
  'medium',
  'If the quadratic equation 2x² - kx + 3 = 0 has two equal real roots, what is the exact value of the parameter k?',
  '["±2√6","±3√2","±4√3","±12"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
