INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-maths-025',
  '"ordered"'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  '["Divide the entire equation by the leading coefficient a: x² + (b/a)x + c/a = 0.","Transpose the constant term to the right-hand side: x² + (b/a)x = -c/a.","Add the square of half the coefficient of x, which is (b / 2a)², to both sides of the equation.","Factorize the left-hand side into a perfect square: (x + b / 2a)² = (b² - 4ac) / 4a².","Extract square roots from both sides and isolate x: x = (-b ± √(b² - 4ac)) / 2a."]'::jsonb,
  'Derivation of quadratic formula: Divide by a -> transpose constant -> add (b/2a)² to both sides -> collapse to binomial square -> extract roots to get x = (-b ± √(b² - 4ac))/2a.'
) ON CONFLICT (question_id) DO UPDATE SET
