INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c10-maths-044',
  10,
  'maths',
  'Pair of Linear Equations in Two Variables',
  'logic',
  'easy',
  'Consider the geometric nature of the linear system:
Assertion (A): The pair of linear equations 2x + 3y = 7 and 4x + 6y = 12 represents two parallel lines having no common solution.
Reason (R): For parallel straight lines, the ratio condition a1/a2 = b1/b2 ≠ c1/c2 is strictly satisfied.',
  '["Both (A) and (R) are true, and (R) correctly explains why the lines are parallel and inconsistent.","Both (A) and (R) are true, but (R) is not the correct explanation of (A).","(A) is true, but (R) is false.","(A) is false, but (R) is true."]'::jsonb,
  NULL,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
