INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c10-maths-045',
  10,
  'maths',
  'Introduction to Trigonometry',
  'logic',
  'hard',
  'Examine the trigonometric simplification:
Assertion (A): The expression (sec A + tan A)(1 - sin A) is identically equal to cos A for any acute angle A.
Reason (R): Rewriting sec A + tan A as (1 + sin A) / cos A and multiplying by (1 - sin A) yields (1 - sin² A) / cos A = cos² A / cos A = cos A.',
  '["Both (A) and (R) are true, and (R) provides the valid algebraic proof of (A).","Both (A) and (R) are true, but (R) is not the correct explanation of (A).","(A) is true, but (R) is false.","(A) is false, but (R) is true."]'::jsonb,
  NULL,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-maths-045',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  '(1/cos A + sin A/cos A)(1 - sin A) = [(1 + sin A)(1 - sin A)] / cos A = (1 - sin² A) / cos A = cos² A / cos A = cos A. Both are true and R proves A.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
