  'c10-maths-056',
  10,
  'maths',
  'Triangles',
  'mcq',
  'hard',
  'Let △ABC ~ △PQR such that area(△ABC) = 64 cm² and area(△PQR) = 121 cm². If corresponding side QR = 15.4 cm, find the length of side BC in cm:',
  '["11.2 cm","12.4 cm","10.8 cm","13.2 cm"]'::jsonb,
  NULL,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
