) VALUES (
  'c10-maths-056',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'The ratio of areas of two similar triangles equals the square of the ratio of their corresponding sides: area(△ABC)/area(△PQR) = (BC/QR)² => 64/121 = (BC/15.4)² => 8/11 = BC/15.4 => BC = (8 × 15.4) / 11 = 8 × 1.4 = 11.2 cm.'
) ON CONFLICT (question_id) DO UPDATE SET
