INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-maths-065',
  '12'::jsonb,
  NULL,
  NULL,
  0,
  NULL,
  NULL,
  'Here a = 9, d = 8, Sₙ = 636. Sₙ = (n/2)[2a + (n - 1)d] => 636 = (n/2)[18 + (n - 1)8] = (n/2)[8n + 10] = n(4n + 5) => 4n² + 5n - 636 = 0. Solving quadratic: D = 5² - 4(4)(-636) = 25 + 10176 = 10201. √D = 101. n = (-5 + 101)/8 = 96/8 = 12 terms.'
) ON CONFLICT (question_id) DO UPDATE SET
