INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c10-maths-074',
  10,
  'maths',
  'Real Numbers',
  'ordering',
  'easy',
  'Arrange the sequential division steps required to compute the HCF of 455 and 42 using Euclid''s Division Algorithm (a = bq + r) from first to last:',
  NULL,
  NULL,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  '["Since remainder 35 ≠ 0, apply division lemma to divisor 42 and remainder 35: 42 = 35 × 1 + 7.","Since remainder 7 ≠ 0, apply division lemma to divisor 35 and remainder 7: 35 = 7 × 5 + 0.","Conclude that the divisor at this final terminal stage (7) is the HCF of 455 and 42.","Observe that the remainder has now become 0.","Apply Euclid''s division lemma to 455 and 42: 455 = 42 × 10 + 35."]'::jsonb,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-maths-074',
  '"ordered"'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  '["Apply Euclid''s division lemma to 455 and 42: 455 = 42 × 10 + 35.","Since remainder 35 ≠ 0, apply division lemma to divisor 42 and remainder 35: 42 = 35 × 1 + 7.","Since remainder 7 ≠ 0, apply division lemma to divisor 35 and remainder 7: 35 = 7 × 5 + 0.","Observe that the remainder has now become 0.","Conclude that the divisor at this final terminal stage (7) is the HCF of 455 and 42."]'::jsonb,
  'Euclidean algorithm: 455 = 42×10 + 35 -> 42 = 35×1 + 7 -> 35 = 7×5 + 0. Remainder is 0, so HCF is the last non-zero divisor, 7.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c10-maths-075',
  10,
  'maths',
  'Surface Areas and Volumes',
  'ordering',
  'hard',
  'Arrange the mathematical steps required to calculate the total external surface area of a composite solid toy formed by mounting a right circular cone of radius r upon a hemisphere of the same radius r:',
  NULL,
  NULL,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  '["Compute the curved surface area of the conical top: CSA(cone) = π r l.","Identify the common radius r shared by the cone and hemisphere, and the vertical height h of the cone.","Calculate the slant height l of the cone using Pythagoras'' theorem: l = √(r² + h²).","Sum the two exposed curved surfaces to obtain Total Area = π r l + 2 π r² = π r (l + 2r).","Compute the curved surface area of the hemispherical bottom: CSA(hemisphere) = 2 π r²."]'::jsonb,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-maths-075',
  '"ordered"'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  '["Identify the common radius r shared by the cone and hemisphere, and the vertical height h of the cone.","Calculate the slant height l of the cone using Pythagoras'' theorem: l = √(r² + h²).","Compute the curved surface area of the conical top: CSA(cone) = π r l.","Compute the curved surface area of the hemispherical bottom: CSA(hemisphere) = 2 π r².","Sum the two exposed curved surfaces to obtain Total Area = π r l + 2 π r² = π r (l + 2r)."]'::jsonb,
  'Composite surface area: Note shared base is internal (hidden) -> compute cone slant height -> calculate cone CSA -> calculate hemisphere CSA -> add both CSAs.'
) ON CONFLICT (question_id) DO UPDATE SET
