) VALUES (
  'c10-maths-077',
  10,
  'maths',
  'Circles',
  'mcq',
  'medium',
  'A tangent PQ at a point P of a circle of radius 5 cm meets a straight line through the centre O at a point Q such that OQ = 12 cm. Find the length of tangent PQ in cm:',
  '["√119 cm","13 cm","12 cm","8.5 cm"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
