INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-maths-087',
  '8'::jsonb,
  NULL,
  NULL,
  0,
  NULL,
  NULL,
  'Let AB be the chord touching inner circle at M. OM ⊥ AB with OM = 3 cm and OA = 5 cm. In right △OMA: AM = √(OA² - OM²) = √(5² - 3²) = √(25 - 9) = √16 = 4 cm. Since perpendicular from centre bisects chord, AB = 2 × AM = 2 × 4 = 8 cm.'
) ON CONFLICT (question_id) DO UPDATE SET
