) VALUES (
  'c10-maths-099',
  10,
  'maths',
  'Statistics',
  'ordering',
  'easy',
  'Arrange the sequential computational steps required to calculate the mode of grouped continuous data using the modal formula Mode = l + [(f1 - f0) / (2f1 - f0 - f2)] × h:',
  NULL,
  NULL,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  '["Inspect the grouped frequency distribution and identify the class interval having the maximum frequency.","Record the lower boundary l and class width h of the modal class.","Substitute all parameters into Mode = l + [(f1 - f0) / (2f1 - f0 - f2)] × h and evaluate the numerical result.","Designate this class interval as the modal class.","Extract f1 (frequency of modal class), f0 (frequency of preceding class), and f2 (frequency of succeeding class)."]'::jsonb,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
