) VALUES (
  'c10-maths-100',
  '"ordered"'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  '["Write the sum Sₙ in forward order: Sₙ = a + (a + d) + (a + 2d) + ... + (a + (n - 1)d).","Write the identical sum Sₙ in reversed reverse order: Sₙ = (a + (n - 1)d) + (a + (n - 2)d) + ... + a.","Add the two equations term-by-term vertically: 2 Sₙ = [2a + (n - 1)d] + [2a + (n - 1)d] + ... (n identical terms).","Consolidate the repeated addition into multiplication: 2 Sₙ = n [2a + (n - 1)d].","Divide both sides by 2 to conclude: Sₙ = (n / 2) [2a + (n - 1)d]."]'::jsonb,
  'Gauss derivation: Forward sum -> Reversed sum -> Vertical addition of n constant pairs -> Simplify 2Sₙ -> Divide by 2.'
) ON CONFLICT (question_id) DO UPDATE SET
