INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-physics-036',
  '-37.5'::jsonb,
  NULL,
  NULL,
  0.2,
  NULL,
  NULL,
  'Object distance u = -25 cm, focal length f = -15 cm. Mirror equation: 1/f = 1/v + 1/u => 1/v = 1/f - 1/u = 1/(-15) - 1/(-25) = -1/15 + 1/25 = (-5 + 3)/75 = -2/75. Thus v = -75/2 = -37.5 cm. The negative sign denotes a real image formed 37.5 cm in front of the mirror.'
) ON CONFLICT (question_id) DO UPDATE SET
