INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-physics-038',
  '64'::jsonb,
  NULL,
  NULL,
  0.5,
  NULL,
  NULL,
  'Initial resistance R₁ = ρl/A = 16 Ω. Upon stretching, volume V = A·l remains constant. When length l'' = 2l, the new cross-sectional area A'' = A/2. The new resistance R'' = ρl''/A'' = ρ(2l)/(A/2) = 4(ρl/A) = 4 × 16 = 64 Ω.'
) ON CONFLICT (question_id) DO UPDATE SET
