INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-physics-043',
  NULL,
  '["Due to atmospheric refraction of starlight through layers of air of varying refractive index.","Turbulent atmospheric layers cause varying refraction and fluctuations in apparent brightness of point-sized stars."]'::jsonb,
  '["atmospheric refraction","optical density","fluctuating","point source"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Starlight enters Earth''s atmosphere and bends towards the normal. Because atmospheric conditions (temperature, density) drift continuously, the apparent position and amount of starlight reaching the eye fluctuate, causing perceived twinkling.'
) ON CONFLICT (question_id) DO UPDATE SET
