INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c10-physics-045',
  10,
  'physics',
  'Light: Reflection and Refraction',
  'logic',
  'hard',
  'Assertion (A): A ray of light incident perpendicular (normally) onto an optical interface separating two distinct media passes into the second medium without any deviation.
Reason (R): When the angle of incidence i = 0°, according to Snell''s law (sin i / sin r = n), the angle of refraction r must also be 0°.',
  '["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."]'::jsonb,
  NULL,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-physics-045',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'By Snell''s law, sin i / sin r = n₂ / n₁. If the ray is normal to the surface, i = 0° => sin i = 0 => sin r = 0 => r = 0°. Thus the refracted ray travels straight ahead along the normal without deviating.'
) ON CONFLICT (question_id) DO UPDATE SET
