INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c10-physics-063',
  '30'::jsonb,
  NULL,
  NULL,
  0.2,
  NULL,
  NULL,
  'For concave lens: f = -15 cm, image distance v = -10 cm (virtual, on same side). Lens formula: 1/f = 1/v - 1/u => 1/u = 1/v - 1/f = 1/(-10) - 1/(-15) = -1/10 + 1/15 = (-3 + 2)/30 = -1/30. Thus u = -30 cm, so magnitude is 30 cm.'
) ON CONFLICT (question_id) DO UPDATE SET
