INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c11-chemistry-042',
  undefined,
  'chemistry',
  'Thermodynamics',
  'image',
  'hard',
  'The graph shows a cyclic thermodynamic process A → B → C → A for an ideal gas on a P-V diagram. What is the net work done by the gas during one complete cycle?',
  '["+8 L·atm","-8 L·atm","+16 L·atm","+4 L·atm"]'::jsonb,
  '{"kind":"svg","src":"<svg xmlns=''http://www.w3.org/2000/svg'' viewBox=''0 0 400 280'' width=''100%'' height=''280''><rect width=''400'' height=''280'' fill=''#0f172a'' rx=''8''/><text x=''200'' y=''25'' fill=''#e2e8f0'' font-size=''14'' text-anchor=''middle'' font-weight=''bold''>Cyclic Process on P-V Diagram</text><line x1=''80'' y1=''230'' x2=''350'' y2=''230'' stroke=''#94a3b8'' stroke-width=''2''/><polygon points=''350,230 340,225 340,235'' fill=''#94a3b8''/><text x=''355'' y=''235'' fill=''#94a3b8'' font-size=''12''>V (L)</text><line x1=''80'' y1=''230'' x2=''80'' y2=''45'' stroke=''#94a3b8'' stroke-width=''2''/><polygon points=''80,45 75,55 85,55'' fill=''#94a3b8''/><text x=''70'' y=''40'' fill=''#94a3b8'' font-size=''12''>P (atm)</text><polygon points=''120,200 280,200 120,80'' fill=''rgba(56,189,248,0.2)'' stroke=''#38bdf8'' stroke-width=''3''/><circle cx=''120'' cy=''80'' r=''5'' fill=''#f59e0b''/><text x=''105'' y=''75'' fill=''#f59e0b'' font-weight=''bold''>A (120, 80) -> P=5, V=2</text><circle cx=''280'' cy=''200'' r=''5'' fill=''#f59e0b''/><text x=''270'' y=''220'' fill=''#f59e0b'' font-weight=''bold''>B (P=1, V=6)</text><circle cx=''120'' cy=''200'' r=''5'' fill=''#f59e0b''/><text x=''95'' y=''215'' fill=''#f59e0b'' font-weight=''bold''>C (P=1, V=2)</text><line x1=''120'' y1=''230'' x2=''120'' y2=''235'' stroke=''#94a3b8'' stroke-width=''2''/><text x=''115'' y=''250'' fill=''#cbd5e1'' font-size=''11''>2</text><line x1=''280'' y1=''230'' x2=''280'' y2=''235'' stroke=''#94a3b8'' stroke-width=''2''/><text x=''275'' y=''250'' fill=''#cbd5e1'' font-size=''11''>6</text><line x1=''75'' y1=''200'' x2=''80'' y2=''200'' stroke=''#94a3b8'' stroke-width=''2''/><text x=''60'' y=''205'' fill=''#cbd5e1'' font-size=''11''>1</text><line x1=''75'' y1=''80'' x2=''80'' y2=''80'' stroke=''#94a3b8'' stroke-width=''2''/><text x=''60'' y=''85'' fill=''#cbd5e1'' font-size=''11''>5</text></svg>"}'::jsonb,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c11-chemistry-042',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'The net work done in a cyclic process equals the area enclosed by the cycle on a P-V indicator diagram. The triangle has base ΔV = 6 - 2 = 4 L and height ΔP = 5 - 1 = 4 atm. Area = (1/2) × 4 × 4 = 8 L·atm. Since the cycle traverses in a clockwise sense (expansion at higher pressure), the work is positive (+8 L·atm).'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

