INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c11-chemistry-046',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'By the Second Law, ΔS_total = ΔS_sys + ΔS_surr > 0 for a spontaneous process. For an isolated system, no heat enters or leaves the surroundings, so q_surr = 0 and ΔS_surr = 0. Therefore, ΔS_total = ΔS_sys > 0.'
) ON CONFLICT (question_id) DO UPDATE SET
