INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c11-english-069',
  NULL,
  '["were should be was","error is were, correction is was","were is replaced by was","was instead of were"]'::jsonb,
  '["were","was"]'::jsonb,
  NULL,
  NULL,
  NULL,
  '''Each'' is an indefinite distributive pronoun that takes a singular verb. The prepositional phrase ''of the shortlisted candidates'' does not alter the singular subject, so ''were'' must be corrected to ''was''.'
) ON CONFLICT (question_id) DO UPDATE SET
