INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c11-english-071',
  11,
  'english',
  'Grammar and Editing',
  'logic',
  'medium',
  'Assertion (A): The sentence ''No sooner had the curtain risen than the audience erupted in thunderous applause'' is grammatically correct.
Reason (R): ''No sooner'' is obligatorily paired with the correlative conjunction ''than'' and triggers inversion of the auxiliary verb before the subject.',
  '["Both Assertion and Reason are true, and Reason is the correct explanation of Assertion.","Both Assertion and Reason are true, but Reason is not the correct explanation of Assertion.","Assertion is true, but Reason is false.","Assertion is false, but Reason is true."]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c11-english-071',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  '''No sooner'' mandates the conjunction ''than'' (never ''when''), and when placed at the head of a clause, demands inverted word order (''had the curtain risen''). Both Assertion and Reason are true, and Reason explains the syntax.'
) ON CONFLICT (question_id) DO UPDATE SET
