) VALUES (
  'c11-hindi-069',
  NULL,
  '["यमक में शब्द की पुनरावृत्ति होती है और अर्थ अलग होते हैं, जबकि श्लेष में एक ही शब्द से कई अर्थ चिपके होते हैं","यमक में एक शब्द बार-बार आकर अलग अर्थ देता है, श्लेष में एक ही शब्द के प्रसंगानुसार कई अर्थ होते हैं"]'::jsonb,
