INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c11-hindi-094',
  NULL,
  '["यांत्रिक माध्यमों द्वारा एक विशाल जनसमूह तक संदेश पहुँचाना जनसंचार कहलाता है","माध्यमों के द्वारा एक साथ विशाल और व्यापक जनसमूह से संवाद स्थापित करना जनसंचार है","विशाल जनसमूह के साथ तकनीकी माध्यमों द्वारा संवाद करना"]'::jsonb,
  '["यांत्रिक माध्यम","विशाल जनसमूह","संवाद","संदेश"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'जनसंचार दो शब्दों से बना है: जन + संचार। जब किसी तकनीकी या यांत्रिक माध्यम (अखबार, रेडियो, टीवी, वेब) की सहायता से समाज के बड़े वर्ग तक सूचनाओं व विचारों का संप्रेषण किया जाए, तो उसे जनसंचार कहते हैं।'
