  'c11-maths-029',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  '(x - 2)/(x + 5) - 2 > 0 => [x - 2 - 2(x + 5)] / (x + 5) > 0 => (-x - 12)/(x + 5) > 0 => (x + 12)/(x + 5) < 0. Testing signs gives the open interval x ∈ (-12, -5).'
) ON CONFLICT (question_id) DO UPDATE SET
