) VALUES (
  'c11-maths-030',
  11,
  'maths',
  'Sequences and Series',
  'mcq',
  'hard',
  'The sum of an infinite geometric progression is 9, and the sum of the squares of its terms is 27. Find the first term a and common ratio r.',
  '["a = 9/2, r = 1/2","a = 6, r = 1/3","a = 3, r = 2/3","a = 5, r = 4/9"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
