INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c11-maths-038',
  '18'::jsonb,
  NULL,
  NULL,
  0,
  NULL,
  NULL,
  '7² = 49 = 50 - 1. 7¹⁰³ = 7 × (7²)⁵¹ = 7 × (50 - 1)⁵¹. Expanding by binomial theorem: (50 - 1)⁵¹ = 25k - 1. So 7 × (25k - 1) = 25m - 7 ≡ -7 ≡ 18 (mod 25). Thus the remainder is 18.'
) ON CONFLICT (question_id) DO UPDATE SET
