) VALUES (
  'c11-maths-080',
  11,
  'maths',
  'Probability',
  'mcq',
  'hard',
  'A postal letter is known to have arrived from either ''TATANAGAR'' or ''CALCUTTA''. On the damaged envelope, only two consecutive letters ''TA'' are visible. What is the probability that the letter originated from ''TATANAGAR''?',
  '["7/11","4/11","2/3","1/2"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
