INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c11-maths-080',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'TATANAGAR (9 letters) has 8 adjacent pairs, of which ''TA'' appears 2 times (P(TA|T) = 2/8 = 1/4). CALCUTTA (8 letters) has 7 adjacent pairs, with ''TA'' appearing 1 time (P(TA|C) = 1/7). By Bayes theorem with equal priors: P(T|TA) = (1/4) / (1/4 + 1/7) = (7/28) / (11/28) = 7/11.'
) ON CONFLICT (question_id) DO UPDATE SET
