INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c11-maths-091',
  '48'::jsonb,
  NULL,
  NULL,
  0,
  NULL,
  NULL,
  'Let the two unknown observations be a and b. Total sum = 7 × 8 = 56. Sum of 5 known = 42 => a + b = 14. Variance = (∑ xᵢ²)/7 - 8² = 16 => ∑ xᵢ² = 7 × 80 = 560. Sum of squares of known 5 = 4 + 16 + 100 + 144 + 196 = 460 => a² + b² = 100. Then (a + b)² = a² + b² + 2ab => 196 = 100 + 2ab => 2ab = 96 => ab = 48.'
) ON CONFLICT (question_id) DO UPDATE SET
