) VALUES (
  'c11-physics-063',
  11,
  'physics',
  'Thermodynamics',
  'numerical',
  'medium',
  'An ideal monoatomic gas (adiabatic index γ = 5/3) at initial temperature T₁ = 400 K expands adiabatically to twice its initial volume (V₂ = 2V₁). Calculate the final gas temperature T₂ in Kelvin rounded to the nearest integer.',
  NULL,
  NULL,
  'K',
  NULL,
  2,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c11-physics-063',
  '252'::jsonb,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  'For an adiabatic process: T₁ V₁^(γ - 1) = T₂ V₂^(γ - 1) => T₂ = T₁ (V₁/V₂)^(2/3) = 400 × (1/2)^(2/3) = 400 / 1.5874 ≈ 252 K.'
) ON CONFLICT (question_id) DO UPDATE SET
