INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-017',
  '"Double fertilisation involves two separate nuclear fusion events within the embryo sac: 1. Syngamy: One haploid male gamete fuses with the haploid egg cell to form a diploid zygote (2n). 2. Triple fusion: The second haploid male gamete fuses with the two haploid polar nuclei (central cell) to form the triploid Primary Endosperm Nucleus (PEN, 3n)."'::jsonb,
  '["Syngamy (fusion of male gamete with egg to form diploid zygote) and Triple fusion (fusion of second male gamete with polar nuclei to form triploid endosperm nucleus)","Fusion of one male gamete with egg cell (syngamy) and second male gamete with central cell polar nuclei (triple fusion)","Double fertilisation consists of syngamy forming zygote and triple fusion forming triploid endosperm"]'::jsonb,
  '["double fertilisation","syngamy","triple fusion","zygote","polar nuclei","primary endosperm nucleus"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Because two fertilisation events (syngamy yielding 2n zygote and triple fusion yielding 3n PEN) occur simultaneously in the same female gametophyte, this process is called double fertilisation.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
