INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-018',
  '"Medical Termination of Pregnancy (MTP) is the voluntary or intentional termination of pregnancy before full term (induced abortion). It is medically and legally considered safest during the first trimester, up to 12 weeks of pregnancy."'::jsonb,
  '["Intentional termination of pregnancy before full term; safest during the first trimester up to 12 weeks","Induced abortion; legally and medically safest up to 12 weeks of pregnancy (first trimester)","Voluntary termination of pregnancy before full term, safest up to 12 weeks"]'::jsonb,
  '["Medical Termination of Pregnancy","MTP","induced abortion","12 weeks","first trimester","safe"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'MTP is safe during the first trimester (up to 12 weeks). Second-trimester terminations (up to 20-24 weeks under MTP Amendment Act) carry significantly higher risk and require approval by medical practitioners.'
) ON CONFLICT (question_id) DO UPDATE SET
