INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-019',
  '"Adaptive radiation is the evolutionary process in which an ancestral species diversifies into a multitude of new morphological forms radiating into different ecological niches. In the Galapagos Islands, an original ancestral seed-eating finch diversified into different geographical island niches, evolving distinct beak shapes adapted for insect-eating, fruit-eating, and cactus-eating diets."'::jsonb,
  '["Evolutionary divergence of an ancestral species into diverse ecological niches; Darwin''s finches diversified from ancestral seed-eaters into insectivorous and vegetarian finches with varied beak adaptations","Diversification of an ancestral species into different ecological niches; illustrated by Darwin''s finches radiating into insectivorous and seed-eating forms with adapted beaks","Process where an ancestral species evolves into diverse forms in different habitats, as seen in Galapagos finches with varied beak shapes"]'::jsonb,
  '["adaptive radiation","ancestral species","ecological niches","Darwin''s finches","beak","Galapagos"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Adaptive radiation exemplifies divergent evolution where starting from a common ancestor in a single geographic area, species radiate outward to occupy diverse environmental niches with specialized morphological adaptations.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
