INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-039',
  '800'::jsonb,
  NULL,
  NULL,
  0,
  NULL,
  NULL,
  'By Chargaff''s rules for double-stranded DNA: %A = %T = 30%. Together, A + T account for 60% of all bases. The remaining 40% consists equally of Guanine and Cytosine (%G = %C = 20%). In a DNA molecule of 4000 total nucleotides: Number of Guanines = 0.20 * 4000 = 800.'
) ON CONFLICT (question_id) DO UPDATE SET
