INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-044',
  '"Plasmodium falciparum is the causative agent of malignant tertian malaria. The infective sporozoites injected by the female Anopheles mosquito initially enter and multiply asexually within the human liver (hepatocytes)."'::jsonb,
  '["Plasmodium falciparum; liver","Plasmodium falciparum causes malignant malaria and reproduces asexually in the liver","P. falciparum; liver cells"]'::jsonb,
  '["Plasmodium falciparum","malignant","liver","sporozoites","asexual multiplication"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Plasmodium falciparum causes malignant tertian malaria which can be fatal. Sporozoites introduced by female Anopheles mosquitoes travel via bloodstream directly to liver cells, where they reproduce asexually (hepatic schizogony) before bursting into erythrocytes.'
