INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-045',
  '"Eli Lilly synthesised two separate artificial DNA nucleotide sequences corresponding to the A and B polypeptide chains of human insulin, inserted them into plasmids of E. coli to produce chains A and B separately, extracted and purified each chain, and combined them chemically by creating disulfide bonds to form active mature human insulin."'::jsonb,
  '["Synthesised separate DNA sequences for chain A and chain B, expressed them separately in E. coli, and linked them by disulfide bonds","Prepared artificial DNA for A and B chains, cloned into E. coli, purified chains separately, and combined them with disulfide bridges","Produced insulin chains A and B separately in E. coli and joined them chemically by disulfide bonds"]'::jsonb,
  '["Eli Lilly","chain A","chain B","E. coli","separate plasmids","disulfide bonds","human insulin"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'In humans, proinsulin contains an extra connecting C-peptide that is excised during maturation. Eli Lilly bypassed C-peptide removal by engineering separate E. coli strains to express chain A and chain B independently, subsequently joining them in vitro via disulfide bridges.'
) ON CONFLICT (question_id) DO UPDATE SET
