INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-067',
  '"Lactic Acid Bacteria (LAB), such as Lactobacillus, convert milk into curd. LAB produce lactic acid that coagulates and partially digests milk proteins (casein), and they significantly increase nutritional value by enriching the curd with Vitamin B12."'::jsonb,
  '["Lactobacillus / Lactic Acid Bacteria (LAB); improves nutrition by increasing Vitamin B12","LAB (Lactobacillus); coagulates milk proteins and enriches Vitamin B12 content","Lactic Acid Bacteria (Lactobacillus), which increases Vitamin B12"]'::jsonb,
  '["Lactic Acid Bacteria","LAB","Lactobacillus","coagulates milk proteins","Vitamin B12","curd"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'LAB ferment lactose to lactic acid, precipitating milk proteins and preventing growth of harmful putrefying microbes in the stomach while synthesizing Vitamin B12.'
) ON CONFLICT (question_id) DO UPDATE SET
