INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-068',
  '"1. Divergent evolution is the diversification of an ancestral homologous structure along different lines in response to different adaptations (e.g., vertebrate forelimbs in whale, bat, cheetah, human). 2. Convergent evolution is the independent evolution of similar analogous functional structures in unrelated organisms occupying similar habitats (e.g., eye of octopus and mammal, or flippers of penguins and dolphins)."'::jsonb,
  '["Divergent evolution arises from common ancestry leading to homologous structures (e.g. vertebrate forelimbs); convergent evolution arises from unrelated ancestors evolving analogous structures for similar niches (e.g. wings of bird and butterfly)","Divergent: common ancestry yielding homologous organs (vertebrate forelimbs); Convergent: different ancestry yielding analogous organs (eye of octopus and mammal)","Divergent evolution forms homologous structures from common ancestor; convergent evolution forms analogous structures independently"]'::jsonb,
  '["divergent evolution","convergent evolution","homologous","analogous","common ancestor","forelimbs","flippers"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Divergent evolution reflects homology and common descent; convergent evolution reflects analogy and independent adaptation to similar selective pressures.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
