INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-069',
  '"Biodiversity hotspots are biogeographical regions with exceptionally high species richness and high degree of endemism (species found nowhere else) that face severe habitat destruction and accelerated threat of extinction. Two major hotspots in India are the Western Ghats (and Sri Lanka) and the Eastern Himalayas (Indo-Burma region)."'::jsonb,
  '["Regions with high species richness and high endemism facing severe habitat threat; Western Ghats and Eastern Himalayas","Areas characterized by exceptional species diversity and high endemism under severe threat; Western Ghats and Indo-Burma/Himalayas","Regions with high species richness and endemism under threat; examples: Western Ghats, Himalayas"]'::jsonb,
  '["biodiversity hotspots","species richness","endemism","habitat loss","Western Ghats","Himalayas"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Norman Myers designated 25 (now 36) global biodiversity hotspots covering less than 2% of Earth''s land surface but containing over 50% of plant species. Western Ghats and Himalayas are prominent Indian hotspots.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
