INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-bio-070',
  12,
  'biology',
  'Principles of Inheritance and Variation',
  'logic',
  'hard',
  'Given below are two statements labeled Assertion (A) and Reason (R):
Assertion (A): In the snapdragon plant (Antirrhinum majus), crossing a true-breeding red-flowered plant (RR) with a true-breeding white-flowered plant (rr) produces an F1 generation with all pink flowers (Rr).
Reason (R): This is an example of incomplete dominance where neither allele is completely dominant over the other, so the heterozygous genotype exhibits an intermediate phenotype.',
  '["Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of Assertion (A).","Both Assertion (A) and Reason (R) are true but Reason (R) is not the correct explanation of Assertion (A).","Assertion (A) is true but Reason (R) is false.","Assertion (A) is false but Reason (R) is true."]'::jsonb,
