INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-093',
  '"Copper-releasing IUDs slowly release copper ions (Cu2+) into the uterine cavity. The released copper ions suppress sperm motility and fertilising capacity, while the physical presence of the IUD promotes phagocytosis of spermatozoa within the uterus, preventing fertilisation."'::jsonb,
  '["Release Cu ions that suppress sperm motility and fertilising capacity, while increasing phagocytosis of sperms in uterus","Cu ions suppress sperm motility and fertilisation capacity and increase phagocytosis of sperms","Copper ions suppress sperm motility and reduce their fertilising power, preventing conception"]'::jsonb,
  '["copper ions","Cu2+","suppress sperm motility","fertilising capacity","phagocytosis","uterus"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Cu ions released from copper-bearing IUDs act as a local spermicide, reducing sperm swimming speed and viability, and preventing successful fertilization.'
) ON CONFLICT (question_id) DO UPDATE SET
