INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-bio-094',
  '"Using Agrobacterium tumefaciens vectors, nematode-specific genes were introduced into the host tobacco plant such that they produced both sense and anti-sense RNA strands. These complementary strands annealed to form double-stranded RNA (dsRNA), which triggered the host''s post-transcriptional RNA interference pathway. When the nematode ingested host cell contents, the dsRNA silenced the specific nematode mRNA, preventing protein translation and causing parasite death."'::jsonb,
  '["Agrobacterium introduces sense and antisense RNA forming dsRNA that silences specific nematode mRNA by post-transcriptional gene silencing","Production of complementary sense and antisense RNAs forms dsRNA that triggers RNAi, silencing specific mRNA of the nematode","Host plant produces dsRNA that silences vital nematode mRNA through RNA interference, killing the parasite"]'::jsonb,
  '["RNA interference","RNAi","sense and anti-sense RNA","dsRNA","silencing","mRNA","Meloidogyne incognita"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'RNAi is a natural cellular defence in eukaryotes. Introducing double-stranded RNA complementary to a nematode essential mRNA targets the viral/foreign mRNA for cleavage by the RISC complex, silencing translation and protecting the plant.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

