  'c12-chem-001',
  12,
  'chemistry',
  'Solutions',
  'mcq',
  'medium',
  'Which of the following equimolar aqueous solutions will exhibit the highest boiling point elevation?',
  '["0.10 m Al2(SO4)3","0.10 m BaCl2","0.10 m NaCl","0.10 m Glucose"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
