INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-001',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Boiling point elevation is a colligative property: Delta T_b = i * K_b * m. For 0.10 m solutions, the elevation is directly proportional to the van ''t Hoff factor i. For Al2(SO4)3, i = 5 (2 Al3+ + 3 SO4 2-); for BaCl2, i = 3; for NaCl, i = 2; and for non-electrolyte glucose, i = 1. Therefore, Al2(SO4)3 has the largest boiling point elevation.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-chem-002',
  12,
  'chemistry',
  'Electrochemistry',
  'mcq',
  'hard',
  'Given standard electrode potentials E°(Zn2+/Zn) = -0.76 V and E°(Cu2+/Cu) = +0.34 V, calculate the EMF of the Daniell cell at 298 K when [Zn2+] = 0.10 M and [Cu2+] = 0.010 M. (Use 2.303 RT / F = 0.0591 V)',
  '["1.070 V","1.100 V","1.130 V","0.980 V"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-002',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Standard cell potential E°_cell = E°_cathode - E°_anode = +0.34 V - (-0.76 V) = +1.10 V. The cell reaction is Zn(s) + Cu2+(aq) -> Zn2+(aq) + Cu(s) with n = 2. By Nernst equation: E_cell = E°_cell - (0.0591 / 2) * log([Zn2+] / [Cu2+]) = 1.10 - 0.02955 * log(0.10 / 0.010) = 1.10 - 0.02955 * log(10) = 1.10 - 0.02955 = 1.07045 V approx 1.070 V.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

