  'c12-chem-017',
  12,
  'chemistry',
  'Coordination Compounds',
  'image',
  'medium',
  'The diagram depicts crystal field splitting of five degenerate d-orbitals in an octahedral ligand field into t2g and eg sets. If the overall splitting energy is Delta_o, what is the energy of the eg set relative to the spherical barycentre?',
  '["+0.6 Delta_o (or +3/5 Delta_o)","-0.4 Delta_o (or -2/5 Delta_o)","+0.4 Delta_o","-0.6 Delta_o"]'::jsonb,
  '{"kind":"svg","src":"<svg viewBox=\"0 0 320 200\" width=\"100%\" height=\"160\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"20\" y1=\"100\" x2=\"100\" y2=\"100\" stroke=\"#64748b\" stroke-width=\"3\"/><text x=\"25\" y=\"85\" font-size=\"12\" fill=\"#1e293b\">Free ion (5 d)</text><line x1=\"120\" y1=\"100\" x2=\"300\" y2=\"100\" stroke=\"#94a3b8\" stroke-dasharray=\"4,4\"/><text x=\"250\" y=\"95\" font-size=\"11\" fill=\"#94a3b8\">Barycentre</text><line x1=\"180\" y1=\"50\" x2=\"260\" y2=\"50\" stroke=\"#ef4444\" stroke-width=\"3\"/><text x=\"270\" y=\"55\" font-size=\"13\" font-weight=\"bold\" fill=\"#ef4444\">eg (dx²-y², dz²)</text><line x1=\"180\" y1=\"140\" x2=\"260\" y2=\"140\" stroke=\"#0284c7\" stroke-width=\"3\"/><text x=\"270\" y=\"145\" font-size=\"13\" font-weight=\"bold\" fill=\"#0284c7\">t2g (dxy, dyz, dxz)</text><line x1=\"165\" y1=\"50\" x2=\"165\" y2=\"140\" stroke=\"#1e293b\" stroke-width=\"1.5\"/><text x=\"135\" y=\"100\" font-size=\"13\" font-weight=\"bold\" fill=\"#1e293b\">Δo</text></svg>"}'::jsonb,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
