INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-017',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'In octahedral crystal field splitting, the barycentre rule requires total energy conservation: 2 * E(eg) + 3 * E(t2g) = 0. The doubly degenerate eg orbitals point directly at incoming ligands and are destabilised by +0.6 Delta_o (+3/5 Delta_o), while triply degenerate t2g orbitals are stabilised by -0.4 Delta_o (-2/5 Delta_o).'
) ON CONFLICT (question_id) DO UPDATE SET
