INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-018',
  '"Aldehydes lacking an alpha-hydrogen atom (such as formaldehyde or benzaldehyde) undergo self-oxidation and reduction (disproportionation) when heated with concentrated alkali (50% NaOH/KOH), producing one molecule of corresponding alcohol and one molecule of carboxylic acid salt."'::jsonb,
  '["Aldehydes having no alpha-hydrogen undergo disproportionation with concentrated alkali to yield an alcohol and a carboxylate salt","Disproportionation of aldehydes lacking alpha-hydrogens in concentrated alkali to form alcohol and carboxylic acid salt","Self oxidation-reduction of aldehydes without alpha hydrogen in concentrated NaOH to give alcohol and carboxylate salt"]'::jsonb,
  '["alpha-hydrogen","disproportionation","concentrated alkali","alcohol","carboxylate salt","oxidation-reduction"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Cannizzaro reaction is a base-catalysed disproportionation specific to aldehydes without alpha-hydrogens (e.g., HCHO, C6H5CHO), where one aldehyde molecule is reduced to an alcohol while another is oxidised to a carboxylate salt.'
) ON CONFLICT (question_id) DO UPDATE SET
