INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-019',
  '"Lanthanoid contraction is the steady and gradual decrease in atomic and ionic radii of the lanthanoid elements with increasing atomic number from Lanthanum (La) to Lutetium (Lu), caused by the poor shielding effect of intervening 4f electrons."'::jsonb,
  '["The steady decrease in atomic and ionic radii along the lanthanoid series due to poor shielding of 4f electrons","Gradual decrease in atomic and ionic size from La to Lu caused by ineffective shielding of imperfect 4f orbitals","Decrease in size of lanthanide elements caused by poor shielding of 4f electrons"]'::jsonb,
  '["decrease in atomic radii","ionic radii","lanthanoid","poor shielding","4f electrons"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Because 4f orbitals have a diffused spatial shape, they shield nuclear charge poorly. With each added proton, the effective nuclear charge Z_eff increases substantially, pulling the electron clouds closer and causing lanthanoid contraction.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-chem-020',
  12,
  'chemistry',
  'Chemical Kinetics',
  'logic',
  'hard',
  'Given below are two statements labeled Assertion (A) and Reason (R):
Assertion (A): For a zero-order reaction, the half-life period t_1/2 is directly proportional to the initial concentration of the reactant.
Reason (R): For a zero-order reaction, the integrated rate equation is [A] = [A]0 - k*t, which leads to t_1/2 = [A]0 / (2k).',
  '["Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of Assertion (A).","Both Assertion (A) and Reason (R) are true but Reason (R) is not the correct explanation of Assertion (A).","Assertion (A) is true but Reason (R) is false.","Assertion (A) is false but Reason (R) is true."]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-020',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Both statements are correct. For a zero-order reaction, rate = k. Integrating gives [A]0 - [A] = kt. Setting [A] = [A]0/2 at t = t_1/2 gives t_1/2 = [A]0 / (2k). Hence, t_1/2 is directly proportional to initial concentration [A]0.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
