) VALUES (
  'c12-chem-036',
  12,
  'chemistry',
  'Solutions',
  'numerical',
  'hard',
  'An aqueous solution of 2.0% (w/w) non-volatile non-electrolyte solute exerts a vapour pressure of 1.004 bar at the normal boiling point of water (where pure water vapour pressure is 1.013 bar). Calculate the molar mass of the solute in g/mol (to one decimal place).',
  NULL,
  NULL,
  'g/mol',
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
