  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-036',
  '41.4'::jsonb,
  NULL,
  NULL,
  0.5,
  NULL,
  NULL,
  'By Raoult''s law for dilute solutions: (P° - P) / P° = (w2 / M2) / (w1 / M1). For 100 g solution, w2 = 2 g, w1 = 98 g of water (M1 = 18 g/mol). (1.013 - 1.004) / 1.013 = (2 / M2) / (98 / 18) => 0.009 / 1.013 = 2 / (5.444 * M2) => 0.008884 = 0.36735 / M2 => M2 = 0.36735 / 0.008884 = 41.35 g/mol approx 41.4 g/mol.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

