) VALUES (
  'c12-chem-038',
  12,
  'chemistry',
  'Chemical Kinetics',
  'numerical',
  'hard',
  'The rate of a chemical reaction quadruples (increases by a factor of 4) when the temperature rises from 293 K to 313 K. Calculate the activation energy Ea in kJ/mol (to one decimal place), given R = 8.314 J K^-1 mol^-1.',
  NULL,
  NULL,
  'kJ/mol',
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-038',
  '52.9'::jsonb,
  NULL,
  NULL,
  0.8,
  NULL,
  NULL,
  'By Arrhenius equation: log(k2 / k1) = Ea / (2.303 * R) * [(T2 - T1) / (T1 * T2)]. log(4) = 0.60206. 0.60206 = Ea / (2.303 * 8.314) * [(313 - 293) / (293 * 313)] = Ea / 19.147 * [20 / 91709] = Ea * 1.139 x 10^-5. Ea = 0.60206 / 1.139 x 10^-5 = 52858 J/mol = 52.86 kJ/mol approx 52.9 kJ/mol.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
