INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-043',
  '"Deprotonation of phenol yields the phenoxide ion, which is resonance stabilized by delocalisation of its negative charge over the ortho and para positions of the aromatic ring. In contrast, the ethoxide ion from ethanol cannot delocalise its negative charge and is destabilised by the electron-donating inductive (+I) effect of the ethyl group."'::jsonb,
  '["Phenoxide ion is resonance stabilized by delocalisation over the benzene ring whereas ethoxide ion is not stabilized and destabilised by +I effect","Resonance stabilization of phenoxide ion distributes negative charge across the ring, making phenol more acidic than ethanol","Phenoxide ion is stabilized by resonance while ethoxide ion is destabilised by the +I effect of the ethyl group"]'::jsonb,
  '["phenoxide ion","resonance stabilization","delocalisation","benzene ring","ethoxide","+I effect"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'The phenoxide ion has 5 resonance contributing structures that spread the negative charge across the aromatic ring, making phenol acidic enough to turn blue litmus red, whereas ethoxide lacks any resonance stabilisation.'
) ON CONFLICT (question_id) DO UPDATE SET
