INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-044',
  '"Faraday''s first law of electrolysis states that the mass of a chemical substance deposited or liberated at any electrode during electrolysis is directly proportional to the total quantity of electric charge (current multiplied by time) passed through the electrolyte: m = Z * Q = Z * I * t."'::jsonb,
  '["The mass of substance liberated at an electrode is directly proportional to the quantity of electricity passed through the electrolyte","Mass deposited is proportional to charge passed, m = ZIt","m = Z * Q where mass deposited is directly proportional to electric charge"]'::jsonb,
  '["mass","directly proportional","quantity of electricity","charge","m = ZIt","electrode"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Faraday''s first law expresses m = Z * I * t, where Z is the electrochemical equivalent of the substance.'
) ON CONFLICT (question_id) DO UPDATE SET
