INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-chem-063',
  12,
  'chemistry',
  'Solutions',
  'numerical',
  'hard',
  'An aqueous solution containing 3.0 g of an unknown protein in 1.00 L of solution develops an osmotic pressure of 0.02463 atm at 300 K. Calculate the molar mass of the protein in g/mol, using universal gas constant R = 0.0821 L atm K^-1 mol^-1.',
  NULL,
  NULL,
  'g/mol',
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-063',
  '3000'::jsonb,
  NULL,
  NULL,
  30,
  NULL,
  NULL,
  'Osmotic pressure pi = C * R * T = (w2 / M2 * V) * R * T. M2 = (w2 * R * T) / (pi * V) = (3.0 g * 0.0821 L atm K^-1 mol^-1 * 300 K) / (0.02463 atm * 1.00 L) = 73.89 / 0.02463 = 3000 g/mol.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-chem-064',
  12,
  'chemistry',
  'Electrochemistry',
  'numerical',
  'hard',
  'The electrical conductivity (kappa) of a 0.001028 M acetic acid solution is 4.95 x 10^-5 S cm^-1. If the limiting molar conductivity Lambda°_m of acetic acid is 390.5 S cm^2 mol^-1, calculate the degree of dissociation (alpha, to three decimal places).',
  NULL,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-064',
  '0.123'::jsonb,
  NULL,
  NULL,
  0.005,
  NULL,
  NULL,
  'Molar conductivity Lambda_m = (kappa * 1000) / M = (4.95 x 10^-5 * 1000) / 0.001028 = 0.0495 / 0.001028 = 48.15 S cm^2 mol^-1. Degree of dissociation alpha = Lambda_m / Lambda°_m = 48.15 / 390.5 = 0.1233 approx 0.123.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
