INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-068',
  '"Chlorobenzene is extremely unreactive towards nucleophilic substitution because: (1) the lone pair of electrons on chlorine is delocalised into the benzene ring by resonance, imparting partial double-bond character to the C-Cl bond; (2) the carbon bonded to chlorine is sp2 hybridised (higher electronegativity, shorter bond length); and (3) electrostatic repulsion exists between the electron-rich pi cloud and the attacking hydroxide nucleophile."'::jsonb,
  '["Due to resonance giving partial double bond character to C-Cl bond, sp2 hybridization of carbon, and repulsion between nucleophile and benzene pi electrons","Partial double bond character from resonance, shorter sp2 C-Cl bond, and pi electron repulsion against incoming nucleophile","Resonance stabilization of C-Cl bond and sp2 hybridization of aromatic carbon make the bond difficult to break"]'::jsonb,
  '["resonance","partial double bond","sp2 hybridisation","C-Cl bond","pi electron cloud","repulsion"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Resonance provides partial double bond character to the C-Cl bond, and the sp2 hybrid carbon holds electrons tightly, requiring drastic conditions (623 K, 300 atm) to displace chloride by hydroxide.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

