INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-069',
  '"A chelate ligand is a polydentate (di- or multi-dentate) ligand that bonds to a single central metal atom through two or more donor atoms, forming one or more heterocyclic ring structures. Chelate complexes possess enhanced thermodynamic stability primarily due to a positive entropy change (Delta S > 0) upon formation, as displacement of multiple monodentate ligands increases the total number of free particles."'::jsonb,
  '["A polydentate ligand forming ring structures with central metal; enhanced stability is due to favorable increase in entropy (chelate effect)","Multidentate ligand that binds through multiple donor atoms forming a ring; stability is due to positive entropy change","Polydentate ligand forming ring with metal; chelate effect gives extra stability due to entropy increase"]'::jsonb,
  '["polydentate","ring","central metal","chelate effect","entropy","thermodynamic stability"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Chelation forms 5- or 6-membered chelate rings. The thermodynamic stability (chelate effect) is entropy-driven: replacing multiple unidentate ligands with a single polydentate ligand yields a net increase in independent molecules in solution.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
