  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-087',
  '0.3'::jsonb,
  NULL,
  NULL,
  0.02,
  NULL,
  NULL,
  'Charge passed Q = I * t = 1.50 A * 600 s = 900 C. Cathode reduction: Cu2+ + 2 e- -> Cu (n = 2). Mass deposited m = (M * Q) / (n * F) = (63.5 g/mol * 900 C) / (2 * 96500 C/mol) = 57150 / 193000 = 0.2961 g approx 0.30 g.'
) ON CONFLICT (question_id) DO UPDATE SET
