INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-092',
  '"An ideal solution is a solution in which each component obeys Raoult''s law at all concentrations and temperatures. It must satisfy: (1) Enthalpy of mixing is zero (Delta_mix H = 0); (2) Volume change of mixing is zero (Delta_mix V = 0)."'::jsonb,
  '["A solution obeying Raoult''s law over entire concentration range where Delta_mix H = 0 and Delta_mix V = 0","A solution that obeys Raoult''s law with Delta H mixing = 0 and Delta V mixing = 0","Obeys Raoult''s law with no change in enthalpy and no change in volume on mixing"]'::jsonb,
  '["ideal solution","Raoult''s law","Delta_mix H = 0","Delta_mix V = 0","enthalpy","volume"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'In an ideal solution, intermolecular forces between solute-solvent (A-B) are identical in magnitude to pure components (A-A and B-B), leading to zero heat change and zero volume change upon mixing.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
