INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-chem-093',
  '"1. Order of a reaction is an experimentally determined quantity that equals the sum of powers of concentration terms in the rate law (can be zero, integer, or fractional). Molecularity is a theoretical concept representing the number of reacting species colliding simultaneously in an elementary step (must be a positive integer 1, 2, or 3, never zero or fractional). 2. Order applies to both elementary and complex multi-step reactions, whereas molecularity is meaningful only for individual elementary reactions."'::jsonb,
  '["Order is experimental and can be fractional or zero; molecularity is theoretical, applies to elementary steps only, and must be non-zero positive integer","Order is experimentally determined and can be zero or fraction; molecularity is theoretical and always a whole number","Order can be zero/fractional and applies to complex reactions; molecularity is only for elementary steps and must be a positive integer"]'::jsonb,
  '["order","molecularity","experimental","theoretical","elementary","zero or fractional","positive integer"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Order is derived from experimental rate law and can be 0, 1/2, 2, etc. Molecularity counts actual colliding reactant molecules in an elementary step and cannot be 0 or fractional.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

