INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-cs-040',
  '3'::jsonb,
  NULL,
  NULL,
  0,
  NULL,
  NULL,
  'Trace:
Push(10) -> [10]
Push(20) -> [10, 20]
Pop() -> [10]
Push(30) -> [10, 30]
Push(40) -> [10, 30, 40]
Push(50) -> [10, 30, 40, 50]
Pop() -> [10, 30, 40]
