INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-018',
  '"Gandhi argued that taking the impoverished and terrified Champaran peasants to court did little good because where the peasantry was so crushed and fear-stricken, law courts were practically useless; the real relief for them lay in becoming free from fear."'::jsonb,
  '["Peasants were crushed and fear-stricken, making law courts useless; real relief was freedom from fear","Because the peasants were terror-stricken and heavily exploited, and courts could not grant true relief until they were freed from fear","Gandhi believed law courts were useless for fear-stricken peasants and the primary need was to free them from fear of the British"]'::jsonb,
  '["crushed","fear-stricken","law courts","useless","free from fear","Champaran"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Gandhi recognized that psychological liberation was the essential first step: until the tenant sharecroppers conquered their crippling fear of British landlords, legal proceedings remained futile.'
) ON CONFLICT (question_id) DO UPDATE SET
