) VALUES (
  'c12-eng-019',
  '"Antarctica holds in its pristine ice-cores half-million-year-old carbon records that reveal Earth''s geological past (Gondwana breakup), current climate changes (melting ice sheets and ozone depletion), and future consequences of global warming without human interference or pollution."'::jsonb,
  '["It preserves half-million-year-old carbon records in ice cores and reveals past, present and future climate change without human distortion","Holds 500,000-year-old carbon records in ice cores and shows real effects of global warming and ozone depletion","Antarctica has pristine ice cores preserving historical carbon records and shows consequences of climate change clearly"]'::jsonb,
  '["ice cores","carbon records","half-million-year","climate change","global warming","Gondwana","pristine"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Antarctica''s untouched ecosystem and ice cores holding 500,000-year-old carbon records make it an open laboratory for analyzing past paleoclimate, current warming trends, and future planetary survival.'
) ON CONFLICT (question_id) DO UPDATE SET
