INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-020',
  '"A shape of beauty lifts the dark pall from our gloomy, despondent spirits, removing disappointment, lack of noble natures, and unhealthful ways, providing eternal joy, peace, and spiritual solace that never fades into nothingness."'::jsonb,
  '["It removes the dark pall from our despondent spirits, providing everlasting joy and solace against sadness and suffering","Lifts the pall of gloom from dark spirits and offers unending joy and quiet breathing","Moves away the pall of sorrow and despondence, giving eternal joy and peace"]'::jsonb,
  '["shape of beauty","removes the pall","dark spirits","despondence","eternal joy","solace"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Keats affirms that amidst human disappointment, malice, and suffering, encounters with natural and artistic beauty dispel despair and permanently nourish the human soul.'
