INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-044',
  '"During a shooting temper tantrum, an extremely talented but naive young actress blew up at the producer. The legal adviser quietly turned on the recording equipment. When she paused for breath, he played back her shrill, enraged voice over the studio speakers. Humiliated and shattered by hearing her own uncontrolled outburst, the terrified girl never acted again."'::jsonb,
  '["He secretly recorded her temper tantrum against the producer and played it back to her, causing such humiliation and shock that she never acted again","Secretly recorded her angry outburst and played it back through the speakers; the humiliation ruined her acting career","He recorded her tirade on tape and played it back, shattering her confidence so she never returned to films"]'::jsonb,
  '["legal adviser","recorded","temper tantrum","played back","speakers","humiliation","career ended"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'The lawyer recorded the actress''s outburst and played it back. Hearing her own unbridled fury over the loudspeakers mortified the unsophisticated girl so deeply that she left the film world permanently.'
) ON CONFLICT (question_id) DO UPDATE SET
