INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-045',
  '"Annan told Bama that because they were born into an oppressed caste, people would never give them dignity or respect on their own. The only way to win respect and throw off these indignities was to study hard, excel in education, stand first in class, and gain learning so people would voluntarily come to her and befriend her."'::jsonb,
  '["He urged her to study with dedication and stand first in class, because education and academic success alone would earn dignity and respect","Study hard and learn everything; education would erase caste indignities and bring people to respect her","Told her that only education and studying hard could overcome untouchability and earn them dignity"]'::jsonb,
  '["study hard","education","stand first","dignity","respect","untouchability","Annan"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Annan inspired Bama by emphasizing education as the great equalizer: if she excelled in school, people would admire her intellect and seek her friendship regardless of caste.'
) ON CONFLICT (question_id) DO UPDATE SET
