INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-046',
  '"1. Person: A formal reply is written strictly in the third person (he/she/they), whereas an informal reply uses first and second person (I/we/you). 2. Format: A formal reply does not use informal salutations or subscriptions (''Yours lovingly''), whereas an informal reply follows ordinary letter format with informal salutation and warm sign-off. 3. Tone and brevity: A formal reply is concise, formal, and objective without personal chatter, whereas an informal reply is warm, conversational, and personal."'::jsonb,
  '["Formal reply uses third person, has no salutation/subscription and concise tone; informal reply uses first person, letter format with personal salutation and warm tone","Formal is in third person, brief, without salutation; informal is in first person with friendly salutation and conversational tone","Formal uses third person and no informal address; informal uses first person, letter format, and warm personal language"]'::jsonb,
  '["third person","first person","salutation","subscription","letter format","formal tone","informal reply"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Formal replies use 3rd person (''Mrs. and Mr. X thank...''), contain no signature, and express brief gratitude. Informal replies read like personal letters in 1st person (''I am thrilled to accept...'').'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

