INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-068',
  '"The hospitable crofter showed the thirty kronor banknotes to the peddler because the peddler looked incredulous when the crofter claimed his cow yielded enough milk to earn thirty kronor last month. The peddler repaid this warm hospitality by returning thirty minutes after departure, smashing the window pane, and stealing the thirty kronor from the leather pouch."'::jsonb,
  '["Crofter showed the money to prove his earnings; peddler returned later, smashed the window and stole the thirty kronor","Showed 30 kronor because peddler seemed doubtful; peddler betrayed him by smashing the window pane and stealing the money","Crofter wanted to prove his cow''s milk earned 30 kronor; peddler smashed the window and stole the money"]'::jsonb,
  '["crofter","incredulous","thirty kronor","smashed the window","stole","leather pouch","betrayed"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'The crofter lived alone and was thrilled to have company, proudly displaying his 30 kronor. The peddler succumbed to temptation, smashed the window, and stole the crofter''s hard-earned savings.'
) ON CONFLICT (question_id) DO UPDATE SET
