INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-069',
  '"Sophie was jealous of Geoff''s silence because she imagined that when he wasn''t speaking, his thoughts wandered into an alluring, vast adult world where she had never been. She felt that there were places, people, and secrets in his life beyond her reach, and she desperately wanted to be admitted into his secret world."'::jsonb,
  '["She imagined his thoughts wandered into an unknown, exotic adult world beyond her reach that she yearned to share","Felt jealous because his silence concealed an exciting world of secrets, people, and places that she was excluded from","Believed his silence hid an unknown world of freedom and experience that she desperately wanted to enter"]'::jsonb,
  '["jealous","silence","unknown world","exotic places","secrets","Geoff","excluded"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'To Sophie, Geoff''s reserve symbolized mystery and freedom: she romanticized his quietness as access to an exciting world from which she was currently excluded.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
