INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-070',
  '"Derry''s mother vehemently forbids him from going, claiming she has heard disturbing rumours about Mr. Lamb and warning Derry that he doesn''t know what kind of man he is. Her reaction reveals narrow-minded societal prejudice: society judges eccentric individuals through gossip and suspicion, reinforcing Derry''s alienation rather than encouraging genuine human connection."'::jsonb,
  '["She forbids him to go based on rumours and gossip; reveals societal prejudice and suspicion toward misunderstood people like Mr. Lamb","Warns him not to go because of neighbourhood gossip; shows how society fears and stigmatizes unconventional people","She stops him because of rumours, showing societal bias and fear of anyone who lives differently"]'::jsonb,
  '["forbids him","rumours","gossip","societal prejudice","suspicion","Mr. Lamb","alienation"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Derry''s mother embodies conformist societal fear: she judges Mr. Lamb by hearsay rather than understanding him, demonstrating how prejudice isolates both Mr. Lamb and Derry.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
