INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-093',
  '"The English visitor was poet and essayist Stephen Spender, editor of the British literary magazine ''The Encounter''. Years after leaving Gemini Studios, Asokamitran bought a low-priced copy of the book ''The God That Failed'' (six essays by prominent writers describing their journey into communism and their disillusioned return). When he saw Stephen Spender''s name among the contributors, the long-standing mystery of the visitor''s identity and his speech at Gemini Studios was instantly unraveled."'::jsonb,
  '["Stephen Spender; Asokamitran discovered his identity years later upon reading the book ''The God That Failed''","Stephen Spender; solved when Asokamitran bought a cheap copy of ''The God That Failed'' featuring Spender''s name","The poet was Stephen Spender; mystery solved through the book ''The God That Failed''"]'::jsonb,
  '["Stephen Spender","The God That Failed","Gemini Studios","The Encounter","mystery solved"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Asokamitran stumbled across ''The God That Failed'' in Madras years later; seeing Spender''s essay suddenly revealed why the anti-communist poet had visited S.S. Vasan''s studio in 1952.'
) ON CONFLICT (question_id) DO UPDATE SET
