INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-094',
  '"In an impulsive wave of unbearable pity and frustration, Frost confesses that it would be a merciful relief to put all these suffering country people out of their pain at one stroke (euthanasia/painless death). However, the next morning, as cool sanity and rational consciousness return, he retracts the desperate thought, wondering how he would feel if someone offered to put him out of his pain in the same manner."'::jsonb,
  '["He suggests putting them out of their pain at one stroke, but retracts it next day when sanity returns, realizing its horrifying moral implication","Momentarily wishes to end their suffering at one stroke, but regains sanity next morning and recognizes the cruelty of such a thought","Proposes putting them out of their misery at one stroke, but next day rational sanity returns and he takes it back"]'::jsonb,
  '["put them out of their pain","at one stroke","retracts","next morning","sanity returns","unbearable pity"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Frost''s momentary wish to put the suffering peasants ''at one stroke out of their pain'' reflects intense emotional despair over their plight, which rational empathy forces him to repudiate upon reflection.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
