INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-eng-095',
  '"General Takima was frail, suffering from chronic cardiac ailment, and relied exclusively on Dr. Sadao''s unparalleled surgical genius to keep him alive. Because the General trusted no other doctor in Japan for his emergency surgery, he could not afford to let Sadao be arrested or executed for harbouring an American prisoner, and even admitted he forgot to send the assassins because of his own self-absorption."'::jsonb,
  '["The General suffered from serious heart disease and trusted only Sadao to operate on him, so he could not afford to execute or arrest Sadao","General needed Sadao''s surgical skill for his own life, so he protected Sadao and forgot to send the assassins due to selfish health worries","Because the General relied on Sadao for his own emergency surgery, he protected Sadao from arrest for treason"]'::jsonb,
  '["General Takima","heart disease","trusted only Sadao","surgical skill","selfish","forgot assassins","could not arrest"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'The General''s supreme self-interest outweighed wartime national security: if Sadao were executed, the General would die on the operating table without a competent surgeon.'
) ON CONFLICT (question_id) DO UPDATE SET
