INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-maths-028',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'dx/dθ = a(1 - cos θ), dy/dθ = a sin θ. dy/dx = (a sin θ) / [a(1 - cos θ)] = cot(θ/2). Then d²y/dx² = [d/dθ(cot(θ/2))] · (dθ/dx) = [-1/2 csc²(θ/2)] / [a(1 - cos θ)]. At θ = π/2: θ/2 = π/4, csc²(π/4) = 2, 1 - cos(π/2) = 1. d²y/dx² = [-1/2 (2)] / [a(1)] = -1/a.'
) ON CONFLICT (question_id) DO UPDATE SET
