  'image',
  'medium',
  'Examine the continuous differentiable curve diagram below with local maximum at x = a and local minimum at x = b. What is the value of the first derivative f''(x) at both stationary points x = a and x = b?',
  '["0","1","-1","Undefined"]'::jsonb,
  '{"kind":"svg","src":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 220\" width=\"100%\" height=\"220\"><rect width=\"520\" height=\"220\" fill=\"#f8fafc\" rx=\"10\"/><text x=\"260\" y=\"25\" font-size=\"15\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Local Extrema and Stationary Points</text><line x=\"40\" y=\"180\" x=\"480\" y=\"180\" stroke=\"#64748b\" stroke-width=\"1.5\"/><line x=\"60\" y=\"30\" x=\"60\" y=\"190\" stroke=\"#64748b\" stroke-width=\"1.5\"/><path d=\"M 80,160 Q 150,20 220,70 T 360,170 Q 420,160 460,90\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2.5\"/><line x=\"130\" y=\"58\" x=\"210\" y=\"58\" stroke=\"#dc2626\" stroke-width=\"2\" stroke-dasharray=\"4\"/><circle cx=\"170\" cy=\"58\" r=\"4\" fill=\"#dc2626\"/><text x=\"170\" y=\"48\" font-size=\"12\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">Local Max at x = a</text><line x=\"320\" y=\"160\" x=\"400\" y=\"160\" stroke=\"#16a34a\" stroke-width=\"2\" stroke-dasharray=\"4\"/><circle cx=\"360\" cy=\"160\" r=\"4\" fill=\"#16a34a\"/><text x=\"360\" y=\"178\" font-size=\"12\" font-weight=\"bold\" fill=\"#16a34a\" text-anchor=\"middle\">Local Min at x = b</text><text x=\"260\" y=\"205\" font-size=\"13\" fill=\"#334155\" text-anchor=\"middle\">Horizontal Tangents at Critical Points: Slope = ?</text></svg>"}'::jsonb,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
