) VALUES (
  'c12-maths-042',
  12,
  'maths',
  'Application of Derivatives',
  'image',
  'hard',
  'Observe the cubic curve y = x³ - 3x below showing concavity transition. At which specific point does the curve switch from concave downward to concave upward (point of inflection)?',
  '["(0, 0)","(1, -2)","(-1, 2)","(√3, 0)"]'::jsonb,
  '{"kind":"svg","src":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 220\" width=\"100%\" height=\"220\"><rect width=\"520\" height=\"220\" fill=\"#f8fafc\" rx=\"10\"/><text x=\"260\" y=\"25\" font-size=\"15\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Inflection Point &amp; Concavity Change: y = x³ - 3x</text><line x=\"50\" y=\"110\" x=\"470\" y=\"110\" stroke=\"#94a3b8\" stroke-width=\"1\"/><line x=\"260\" y=\"30\" x=\"260\" y=\"190\" stroke=\"#94a3b8\" stroke-width=\"1\"/><path d=\"M 100,190 C 180,30 230,60 260,110 C 290,160 340,190 420,30\" fill=\"none\" stroke=\"#4f46e5\" stroke-width=\"2.5\"/><circle cx=\"260\" cy=\"110\" r=\"5\" fill=\"#ef4444\"/><text x=\"275\" y=\"105\" font-size=\"13\" font-weight=\"bold\" fill=\"#ef4444\">(0, 0)</text><text x=\"160\" y=\"80\" font-size=\"12\" fill=\"#b45309\">Concave Down: f''''(x) &lt; 0</text><text x=\"340\" y=\"140\" font-size=\"12\" fill=\"#15803d\">Concave Up: f''''(x) &gt; 0</text></svg>"}'::jsonb,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
