  'c12-maths-066',
  12,
  'maths',
  'Application of Integrals',
  'image',
  'medium',
  'Examine the shaded region under the line y = x + 1 bounded by the x-axis from x = 0 to x = 4. What is the exact area of this trapezoidal region?',
  '["12","16","10","14"]'::jsonb,
  '{"kind":"svg","src":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 220\" width=\"100%\" height=\"220\"><rect width=\"520\" height=\"220\" fill=\"#f8fafc\" rx=\"10\"/><text x=\"260\" y=\"25\" font-size=\"15\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Definite Integral as Area Under Curve: y = x + 1</text><line x=\"50\" y=\"180\" x=\"470\" y=\"180\" stroke=\"#64748b\" stroke-width=\"1.5\"/><line x=\"80\" y=\"30\" x=\"80\" y=\"190\" stroke=\"#64748b\" stroke-width=\"1.5\"/><polygon points=\"80,180 80,150 400,30 400,180\" fill=\"#dbeafe\" stroke=\"#2563eb\" stroke-width=\"2\"/><line x=\"80\" y=\"150\" x=\"400\" y=\"30\" stroke=\"#1d4ed8\" stroke-width=\"2.5\"/><text x=\"80\" y=\"195\" font-size=\"12\" fill=\"#475569\" text-anchor=\"middle\">x = 0</text><text x=\"400\" y=\"195\" font-size=\"12\" fill=\"#475569\" text-anchor=\"middle\">x = 4</text><text x=\"70\" y=\"150\" font-size=\"11\" fill=\"#1e40af\" text-anchor=\"end\">(0, 1)</text><text x=\"410\" y=\"30\" font-size=\"11\" fill=\"#1e40af\" text-anchor=\"start\">(4, 5)</text><text x=\"240\" y=\"120\" font-size=\"14\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Area = ∫₀⁴ (x + 1) dx = ?</text></svg>"}'::jsonb,
  NULL,
  NULL,
  2,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
