  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Substituting t = a - x gives dx = -dt; limits change from x=0→t=a and x=a→t=0. Thus -∫ₐ⁰ f(a - t) dt = ∫₀ᵃ f(a - t) dt = ∫₀ᵃ f(a - x) dx.'
) ON CONFLICT (question_id) DO UPDATE SET
