) VALUES (
  'c12-phy-021',
  '96'::jsonb,
  NULL,
  NULL,
  0.5,
  NULL,
  NULL,
  'Initial capacitance C₀ = ε₀A / d = 8 pF. With new distance d'' = d/2 and dielectric K = 6: C'' = K · ε₀A / (d/2) = 2K · (ε₀A/d) = 2 × 6 × 8 = 96 pF.'
) ON CONFLICT (question_id) DO UPDATE SET
