INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-phy-051',
  12,
  'physics',
  'Electric Charges and Fields',
  'mcq',
  'hard',
  'An electric dipole of moment p is placed in a uniform electric field E at an angle theta with the field. What is the work done in rotating the dipole from stable equilibrium (theta = 0) to unstable equilibrium (theta = 180 degrees)?',
  '["pE","2pE","-2pE","Zero"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-051',
  '1'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Potential energy of dipole is U(theta) = -pE cos(theta). At stable equilibrium (theta = 0), U(0) = -pE. At unstable equilibrium (theta = 180°), U(180°) = -pE cos(180°) = +pE. Work done W = U(180°) - U(0) = pE - (-pE) = 2pE.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-phy-052',
  12,
  'physics',
  'Electrostatic Potential and Capacitance',
  'mcq',
  'hard',
  'A parallel plate capacitor with air between the plates has capacitance C0. It is charged to a potential V0 and then disconnected from the battery. A dielectric slab of dielectric constant K is then completely inserted between the plates. What are the new capacitance C, potential difference V, and stored energy U compared to original values C0, V0, U0?',
  '["C = K C0, V = V0/K, U = U0/K","C = K C0, V = K V0, U = K U0","C = C0/K, V = V0/K, U = U0","C = K C0, V = V0, U = U0/K"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-052',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'When battery is disconnected, charge Q remains constant (Q = C0 V0). On inserting dielectric, capacitance becomes C = K C0. The potential difference becomes V = Q/C = (C0 V0)/(K C0) = V0/K. The stored energy becomes U = Q^2 / (2C) = Q^2 / (2 K C0) = U0/K.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-phy-053',
  12,
  'physics',
  'Current Electricity',
  'mcq',
  'medium',
  'A potentiometer wire of length 10 m and resistance 20 ohms is connected in series with a battery of emf 3 V (negligible internal resistance) and a series resistance of 10 ohms. What is the potential gradient along the potentiometer wire?',
  '["0.20 V/m","0.15 V/m","0.30 V/m","0.10 V/m"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-053',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Total circuit resistance = R_wire + R_series = 20 + 10 = 30 ohms. Current I = E / R_total = 3 V / 30 ohms = 0.1 A. Potential drop across the 10 m wire V_wire = I * R_wire = 0.1 A * 20 ohms = 2.0 V. Potential gradient k = V_wire / L = 2.0 V / 10 m = 0.20 V/m.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
