INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-phy-057',
  12,
  'physics',
  'Ray Optics and Optical Instruments',
  'mcq',
  'medium',
  'A compound microscope has an objective of focal length 1.25 cm and an eyepiece of focal length 5.0 cm. A small object is kept at 1.5 cm from the objective. If the final image is formed at the near point (D = 25 cm), what is the total magnifying power?',
  '["20","25","30","15"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-057',
  '2'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Magnification by objective: 1/v_o - 1/u_o = 1/f_o => 1/v_o - 1/(-1.5) = 1/1.25 => 1/v_o = 1/1.25 - 1/1.5 = 0.8 - 0.6667 = 0.1333 => v_o = 7.5 cm. Linear magnification m_o = |v_o / u_o| = 7.5 / 1.5 = 5. Magnification by eyepiece at near point m_e = (1 + D / f_e) = (1 + 25 / 5) = 6. Total magnification M = m_o * m_e = 5 * 6 = 30.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
  id, class, subject, chapter, type, difficulty, question, options, image, unit, hint, marks,
  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-phy-058',
  12,
  'physics',
  'Wave Optics',
  'mcq',
  'hard',
  'In Young''s double slit experiment, yellow light of wavelength 600 nm produces fringes of width 2.0 mm on a screen. If a thin transparent mica sheet of refractive index 1.6 is placed in front of one of the slits, the central bright fringe shifts by a distance equal to 4 fringe widths. What is the thickness of the mica sheet?',
  '["4.0 micrometres","2.4 micrometres","6.0 micrometres","8.0 micrometres"]'::jsonb,
  NULL,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-058',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Path difference introduced by sheet of thickness t and refractive index mu is (mu - 1) t. Fringe shift Delta y = [D / d] * (mu - 1) t. Since fringe width beta = lambda * D / d, shift Delta y = [(mu - 1) t / lambda] * beta. We are given Delta y = 4 beta. Therefore, (mu - 1) t / lambda = 4 => t = 4 * lambda / (mu - 1) = 4 * 600 nm / (1.6 - 1) = 2400 nm / 0.6 = 4000 nm = 4.0 micrometres.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
  keywords = EXCLUDED.keywords,
  tolerance = EXCLUDED.tolerance,
  pairs = EXCLUDED.pairs,
  ordered_items = EXCLUDED.ordered_items,
  explanation = EXCLUDED.explanation;

INSERT INTO public.questions_public (
