) VALUES (
  'c12-phy-059',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'Work function phi_0 = h * nu_0. Therefore, threshold frequency nu_0 = phi_0 / h = (2.14 * 1.6 * 10^-19 J) / (6.63 * 10^-34 J s) = 3.424 * 10^-19 / 6.63 * 10^-34 = 5.16 x 10^14 Hz.'
) ON CONFLICT (question_id) DO UPDATE SET
