  pairs_left, pairs_right_shuffled, items_shuffled, passage_id, passage_order
) VALUES (
  'c12-phy-069',
  12,
  'physics',
  'Ray Optics and Optical Instruments',
  'image',
  'medium',
  'Examine the optical path of light rays passing symmetrically through an equilateral glass prism of apex angle A = 60 degrees. If the angle of minimum deviation D_m is measured to be 30 degrees, what is the refractive index of the prism material?',
  '["sqrt(2) approx 1.414","1.500","sqrt(3) approx 1.732","1.333"]'::jsonb,
  '{"kind":"svg","src":"<svg viewBox=\"0 0 320 200\" width=\"100%\" height=\"160\" xmlns=\"http://www.w3.org/2000/svg\"><polygon points=\"160,30 60,170 260,170\" fill=\"#f0f9ff\" stroke=\"#0284c7\" stroke-width=\"2.5\"/><line x1=\"20\" y1=\"130\" x2=\"110\" y2=\"105\" stroke=\"#ef4444\" stroke-width=\"2\"/><line x1=\"110\" y1=\"105\" x2=\"210\" y2=\"105\" stroke=\"#ef4444\" stroke-width=\"2\"/><line x1=\"210\" y1=\"105\" x2=\"300\" y2=\"130\" stroke=\"#ef4444\" stroke-width=\"2\"/><line x1=\"110\" y1=\"105\" x2=\"260\" y2=\"70\" stroke=\"#94a3b8\" stroke-dasharray=\"3,3\"/><line x1=\"210\" y1=\"105\" x2=\"60\" y2=\"70\" stroke=\"#94a3b8\" stroke-dasharray=\"3,3\"/><text x=\"150\" y=\"25\" font-size=\"14\" font-weight=\"bold\" fill=\"#0284c7\">A = 60°</text><text x=\"145\" y=\"80\" font-size=\"12\" fill=\"#ef4444\">r₁ = r₂</text><text x=\"160\" y=\"190\" font-size=\"13\" font-weight=\"bold\" fill=\"#1b2a4a\">Equilateral Prism</text></svg>"}'::jsonb,
  NULL,
  NULL,
  1,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL
) ON CONFLICT (id) DO UPDATE SET
  question = EXCLUDED.question,
  options = EXCLUDED.options,
  image = EXCLUDED.image,
  marks = EXCLUDED.marks,
  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

