INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-070',
  '"Mass defect is the difference between the total mass of the individual constituent nucleons (protons and neutrons) and the actual rest mass of the bound nucleus: Delta m = [Z*m_p + (A - Z)*m_n] - M. According to Einstein''s mass-energy equivalence, this mass difference is converted into nuclear binding energy: E = (Delta m) * c^2."'::jsonb,
  '["Mass defect is the difference between the total mass of the individual constituent nucleons and the actual rest mass of the bound nucleus","Difference between mass of nucleons and actual mass of nucleus","Delta m = Z*mp + (A-Z)*mn - M and E = mc^2","Mass defect is the mass lost when nucleons bind together into a nucleus, related by E = mc^2"]'::jsonb,
  '["mass defect","nucleons","rest mass","binding energy","Delta m","E = mc^2"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Mass defect represents the mass converted into binding energy during nucleus formation from separate protons and neutrons according to Einstein''s relation E = Delta m * c^2.'
) ON CONFLICT (question_id) DO UPDATE SET
  answer = EXCLUDED.answer,
  accepted_answers = EXCLUDED.accepted_answers,
