INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-080',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'The central maximum in Fraunhofer single-slit diffraction extends from the first minimum on one side (theta = -lambda/a) to the first minimum on the other side (theta = +lambda/a). Angular width 2 theta = 2 * lambda / a. Linear width w = 2 * lambda * D / a = 2 * (500 x 10^-9 m) * (2.0 m) / (0.1 x 10^-3 m) = 2000 x 10^-9 / 10^-4 = 2 x 10^-2 m = 20 mm.'
) ON CONFLICT (question_id) DO UPDATE SET
