  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-081',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'The velocity component perpendicular to the field v_perp = v sin theta produces circular motion with time period T = 2 pi m / (q B). The component parallel to the field v_parallel = v cos theta remains unaffected and produces linear translation along B. The pitch is the distance traveled along B in one time period: Pitch = v_parallel * T = (v cos theta) * (2 pi m / (q B)) = (2 pi m v cos theta) / (q B).'
) ON CONFLICT (question_id) DO UPDATE SET
