INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-089',
  '8.16'::jsonb,
  NULL,
  NULL,
  0.05,
  NULL,
  NULL,
  'For a balanced metre bridge: X / Y = l / (100 - l). Given l = 39.5 cm and Y = 12.5 ohms: X = Y * [l / (100 - l)] = 12.5 * [39.5 / (100 - 39.5)] = 12.5 * [39.5 / 60.5] = 12.5 * 0.65289 = 8.16 ohms.'
) ON CONFLICT (question_id) DO UPDATE SET
