INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-091',
  '3.24'::jsonb,
  NULL,
  NULL,
  0.08,
  NULL,
  NULL,
  'Capacitive reactance X_C = 1 / (2 * pi * f * C) = 1 / (2 * 3.1416 * 60 * 100 x 10^-6) = 1 / 0.0377 = 26.53 ohms. Impedance Z = sqrt(R^2 + X_C^2) = sqrt(40^2 + 26.53^2) = sqrt(1600 + 703.8) = sqrt(2303.8) = 48.0 ohms. RMS current I_rms = V_rms / Z = 110 V / 48.0 ohms = 2.292 A. Peak current I_0 = sqrt(2) * I_rms = 1.414 * 2.292 A = 3.24 A.'
) ON CONFLICT (question_id) DO UPDATE SET
