INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-094',
  '"Silicon is preferred because it has a wider energy band gap (1.1 eV vs 0.72 eV for Ge), resulting in substantially lower reverse saturation leakage current, and it operates reliably at higher temperatures with higher breakdown voltages."'::jsonb,
  '["Silicon has a larger band gap (1.1 eV) resulting in smaller reverse leakage current and higher temperature stability","Larger energy band gap and higher operating temperature capability with lower reverse leakage current","Higher band gap and lower reverse saturation current","Silicon can operate at higher temperatures and has smaller leakage current than germanium"]'::jsonb,
  '["band gap","reverse saturation","leakage current","temperature","silicon"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Silicon''s wider band gap (1.1 eV) drastically reduces thermally generated minority carrier leakage current and allows stable operation up to 150°C-200°C compared to germanium''s limit of ~75°C.'
) ON CONFLICT (question_id) DO UPDATE SET
