INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-095',
  '"The two light sources must be coherent (maintaining a constant phase difference over time), must emit light of identical wavelength (monochromatic), and should have narrow slit widths close to each other."'::jsonb,
  '["The two sources must be coherent and monochromatic","Constant phase difference (coherent sources) and same wavelength (monochromatic light)","Coherent sources and equal or nearly equal amplitudes","Monochromatic light and coherent sources"]'::jsonb,
  '["coherent","monochromatic","constant phase difference","wavelength"]'::jsonb,
  NULL,
  NULL,
  NULL,
  'Sustained interference requires coherent sources that maintain a time-independent phase difference, and monochromatic light to prevent overlapping colour fringes.'
) ON CONFLICT (question_id) DO UPDATE SET
