  pairs_left = EXCLUDED.pairs_left,
  pairs_right_shuffled = EXCLUDED.pairs_right_shuffled,
  items_shuffled = EXCLUDED.items_shuffled;

INSERT INTO public.question_answers (
  question_id, answer, accepted_answers, keywords, tolerance, pairs, ordered_items, explanation
) VALUES (
  'c12-phy-096',
  '0'::jsonb,
  NULL,
  NULL,
  NULL,
  NULL,
  NULL,
  'According to the Maxwell-Ampere circuital law: oint B · dl = mu0 * (I_c + I_d). In the gap between plates, conduction current I_c = 0, but the changing electric flux produces displacement current I_d = eps0 * (d Phi_E / dt), producing a magnetic field identical to that produced by conduction current.'
) ON CONFLICT (question_id) DO UPDATE SET
